window.LS=[{"id":"p3-01","part":3,"level":1,"topic":"IT","title":"Sprint deadline moved","title_vi":"Dời hạn sprint","speakers":{"A":"M-US","B":"F-GB"},"lines":[["A","Hi Emma, have you got a minute? I need to talk to you about the sprint deadline."],["B","Sure, Mark. Is something wrong? You sound a bit worried."],["A","Well, the payment team just told me their new API won't be ready until next Monday."],["B","Oh no. We can't finish the checkout page without it, can we?"],["A","Not really. So I'd like to move our deadline from this Friday to next Thursday. That gives us three days to test."],["B","That sounds reasonable. Have you told the client yet?"],["A","Not yet. I wanted to touch base with you first before we tell anyone."],["B","OK. I'll send them an email this afternoon and explain the delay."],["A","Great, thanks. And could you loop in the QA team too?"],["B","Sure. I'll copy them on the email so everyone's on the same page."]],"questions":[{"q":"What problem are the speakers discussing?","o":["A client has cancelled the project","Another team's API will be late","The checkout page has a bug","The QA team is too busy"],"a":1,"ev":[2],"vi":"Người đàn ông nói \"their new API won't be ready until next Monday\" – API của nhóm khác bị trễ. Bẫy: \"checkout page\" có xuất hiện nhưng không phải bị lỗi."},{"q":"When is the new deadline?","o":["This Friday","Next Monday","In three days","Next Thursday"],"a":3,"ev":[4],"vi":"\"move our deadline from this Friday to next Thursday\". Bẫy: Friday là hạn cũ, Monday là ngày API xong."},{"q":"What does the woman say she will do this afternoon?","o":["Call the payment team","Test the checkout page","Email the client","Meet with the QA team"],"a":2,"ev":[7],"vi":"\"I'll send them an email this afternoon\" – \"them\" là khách hàng (the client)."},{"q":"What does the man ask the woman to do?","o":["Include the QA team","Delay the testing","Update the API","Reschedule a meeting"],"a":0,"ev":[8],"vi":"\"could you loop in the QA team\" – loop in = đưa ai vào cuộc trao đổi, tức là include."}],"ts":[0.4,6.3,13.16,18.75,25.14,33.2,38.93,44.09,50.69,55.01]},{"id":"p3-02","part":3,"level":2,"topic":"IT","title":"Critical bug before release","title_vi":"Lỗi nghiêm trọng trước ngày phát hành","speakers":{"A":"F-AU","B":"M-US"},"lines":[["A","Hey Daniel, got a sec? QA just found a critical bug in the login flow."],["B","Seriously? The release is tomorrow morning at nine."],["A","I know. Users with two-factor authentication can't sign in at all. That's roughly fifteen percent of our customers."],["B","That's a big chunk. Who's the best person to fix it?"],["A","Priya wrote that module, but she's on leave until Thursday."],["B","Hmm. What about Tom? He reviewed her code last month."],["A","He could, but he's already flat out with the database migration."],["B","OK, I'll take it myself, then. If it's a simple fix, I should have it done by tonight."],["A","And if it isn't?"],["B","Then we'll push the release to Friday. I'll give the product manager a heads-up just in case."],["A","Good idea. I'll ask QA to stay a bit later to retest."]],"questions":[{"q":"What problem does the woman report?","o":["Some users are unable to log in","A database migration has failed","A team member has resigned","The release notes are missing"],"a":0,"ev":[0,2],"vi":"\"Users with two-factor authentication can't sign in at all\" = không đăng nhập được. Bẫy: \"database migration\" là việc của Tom, không phải sự cố."},{"q":"Why can't Priya fix the bug?","o":["She is busy with a migration","She is not familiar with the code","She is away until Thursday","She is reviewing another project"],"a":2,"ev":[4],"vi":"\"she's on leave until Thursday\" = đang nghỉ phép. Bẫy: bận migration là Tom, không phải Priya."},{"q":"What does the woman mean when she says, \"he's already flat out with the database migration\"?","o":["Tom has finished the migration","Tom has no time to help","The migration has been cancelled","Tom needs help with the database"],"a":1,"ev":[6],"vi":"\"flat out\" = cực kỳ bận, nên Tom không có thời gian giúp sửa lỗi."},{"q":"According to the man, what will happen if the fix is not simple?","o":["QA will retest on Thursday","Priya will return early","Tom will take over the fix","The release will move to Friday"],"a":3,"ev":[8,9],"vi":"\"Then we'll push the release to Friday\" – push = dời lại. Bẫy: Thursday là ngày Priya quay lại."}],"ts":[0.4,7.43,12.92,23.36,28.76,33.92,40.64,45.99,53.81,56.3,63.79]},{"id":"p3-03","part":3,"level":3,"topic":"IT","title":"Client change request","title_vi":"Yêu cầu thay đổi từ khách hàng","speakers":{"A":"F-US","B":"M-GB"},"lines":[["A","Oliver, Northwind just sent a change request. They want the dashboard to export to PDF as well as Excel."],["B","At this stage? We're only two weeks from handover."],["A","I know. I've had a rough look, and I think it's about forty extra hours of work."],["B","Forty hours at our standard rate is, what, around six thousand dollars?"],["A","Right. But they've mentioned the budget's tight, so they might push back."],["B","Well, we could offer the PDF export as a phase-two item. That way the handover date stays on the fifteenth."],["A","That's an option. Or we deliver everything on the twenty-ninth, if they're willing to pay the full amount."],["B","Let's give them both and let them choose. Can you put together a short estimate?"],["A","Sure. I'll have it ready by tomorrow noon. Should I copy in their project manager?"],["B","Yes, please. And I'll set up a call with them on Thursday to walk through it."]],"questions":[{"q":"What does the client want?","o":["A reduced project budget","Another export option in the dashboard","An earlier handover date","Extra hours of support"],"a":1,"ev":[0],"vi":"\"export to PDF as well as Excel\" được diễn đạt lại thành \"another export option\". Bẫy: \"budget\", \"hours\" có trong bài nhưng không phải yêu cầu."},{"q":"How much would the change cost?","o":["About $4,000","About $6,000","About $15,000","About $40,000"],"a":1,"ev":[3],"vi":"\"around six thousand dollars\". Bẫy: forty (giờ công) và fifteen (ngày bàn giao) là số gây nhiễu."},{"q":"What does the man suggest?","o":["Moving the handover to the twenty-ninth","Hiring an extra developer","Asking the client for more budget","Delivering one feature at a later stage"],"a":3,"ev":[5],"vi":"\"offer the PDF export as a phase-two item\" = giao tính năng ở giai đoạn sau. Bẫy: ngày 29 là đề xuất của người phụ nữ."},{"q":"What will the woman do by tomorrow noon?","o":["Hold a call with the client","Finish the PDF export","Prepare a cost estimate","Revise the budget"],"a":2,"ev":[7,8],"vi":"\"put together a short estimate\" – \"I'll have it ready by tomorrow noon\". Bẫy: cuộc gọi thứ Năm là việc của người đàn ông."}],"ts":[0.4,8.99,14.39,21.23,27.27,33.49,42.1,49.47,55.82,63.55]},{"id":"p3-04","part":3,"level":1,"topic":"Office","title":"Booking a workshop room","title_vi":"Đặt phòng cho buổi workshop","speakers":{"A":"F-US","B":"M-AU"},"lines":[["A","Hi, this is Sarah from Marketing. I'd like to book a meeting room for a workshop next Tuesday."],["B","Sure. Is it a full day or a half day?"],["A","Just the morning, from nine to one. There'll be about twenty people."],["B","OK, let me check. Room 5B holds twenty-five, and it's free that morning. It's on the fifth floor, right next to the lifts."],["A","Perfect. Does it have a projector?"],["B","Yes, it does. But the microphone in that room isn't working right now."],["A","Oh. Could we borrow a portable one?"],["B","Sure, I can bring one up from the IT office on Monday afternoon."],["A","That'd be great. Also, we'll need two flip charts."],["B","No problem, there are a couple in the storage room. I'll send you a confirmation email in a few minutes, and just let me know if anything changes."]],"questions":[{"q":"Why is the woman calling?","o":["To fix a projector","To reserve a room","To order office supplies","To hire a speaker"],"a":1,"ev":[0],"vi":"\"I'd like to book a meeting room\" – book = reserve."},{"q":"How many people will attend the workshop?","o":["Nine","Twenty-five","Two","About twenty"],"a":3,"ev":[2],"vi":"\"There'll be about twenty people\". Bẫy: 25 là sức chứa phòng, 9 là giờ bắt đầu."},{"q":"What problem does the man mention?","o":["The room is already booked","The projector is old","A microphone is broken","The flip charts are missing"],"a":2,"ev":[5],"vi":"\"the microphone in that room isn't working\" = micro bị hỏng."},{"q":"What does the man offer to do on Monday?","o":["Bring a portable microphone","Set up the projector","Send an invoice","Move the workshop"],"a":0,"ev":[6,7],"vi":"\"I can bring one up from the IT office on Monday afternoon\" – \"one\" = portable microphone."}],"ts":[0.4,6.76,10.45,15.47,24.87,28.16,33.58,36.84,41.76,46.32]},{"id":"p3-05","part":3,"level":2,"topic":"Logistics","title":"Supplier shipment delayed","title_vi":"Lô hàng nhà cung cấp bị trễ","speakers":{"A":"M-GB","B":"F-AU","C":"M-US"},"lines":[["A","Thanks for joining, both of you. Bad news: the circuit boards from our supplier in Shenzhen are stuck at the port."],["B","How long is the delay, James?"],["A","They're saying ten days, maybe longer, because of a customs inspection."],["C","That's going to hit our production line. We've only got enough stock for about a week."],["B","Could we ship part of the order by air instead?"],["A","We could, but air freight would cost an extra four thousand dollars."],["C","Honestly, that's peanuts compared to shutting down the line."],["B","Agreed. There's also a distributor in Singapore that keeps some of these boards in stock."],["A","Good thinking, Lucy. Could you contact them today and ask about prices?"],["B","Sure, I'll call them after lunch."],["C","And I'll let the production manager know what's going on, so he can plan around it."]],"questions":[{"q":"Why is the shipment delayed?","o":["The supplier ran out of stock","The goods are being checked by customs","The air freight was cancelled","The production line shut down"],"a":1,"ev":[2],"vi":"\"because of a customs inspection\" = hải quan đang kiểm tra hàng."},{"q":"How long will the company's current stock last?","o":["About ten days","About four days","About a month","About a week"],"a":3,"ev":[3],"vi":"\"enough stock for about a week\". Bẫy: ten days là thời gian trễ hàng."},{"q":"What does one of the men mean when he says, \"that's peanuts compared to shutting down the line\"?","o":["The extra cost is worth paying","Air freight is too expensive","The line should stop for a while","The supplier should pay the cost"],"a":0,"ev":[5,6],"vi":"\"peanuts\" = số tiền rất nhỏ; 4.000 đô vẫn đáng trả hơn là dừng dây chuyền."},{"q":"What will the woman do this afternoon?","o":["Visit the port","Speak to the production manager","Call a distributor","Cancel the original order"],"a":2,"ev":[7,8,9],"vi":"Lucy nói \"I'll call them after lunch\" – \"them\" là nhà phân phối ở Singapore. Bẫy: báo production manager là việc của người đàn ông kia."}],"ts":[0.4,9.09,12.64,18.18,24.1,28.13,33.2,37.35,44.98,51.5,55.24]},{"id":"p3-06","part":3,"level":3,"topic":"HR","title":"Onboarding a new hire","title_vi":"Chuẩn bị cho nhân viên mới","speakers":{"A":"F-GB","B":"M-US"},"lines":[["A","Hi Kevin, it's Rachel from HR. Our new back-end developer, Minh, starts on Monday the third."],["B","Right, she's on my list. Her laptop arrived yesterday, but I still need to install the dev tools."],["A","Will it be ready in time?"],["B","Should be. I'll finish it by Friday afternoon. Her email's already active, but I can't open up repository access until her manager approves it."],["A","That'd be Alan. He's at a conference until Wednesday, though."],["B","Then she won't be able to touch the code for her first two days."],["A","Not ideal. Could his deputy, Joanna, sign it off instead?"],["B","Yes, any team lead can approve it. I'll send Joanna the request now."],["A","Great. And the access badge?"],["B","Security only prints badges at the start of the week, so she'll collect it from the front desk at ten on her first day."],["A","Fine. I'll mention that in her welcome email."]],"questions":[{"q":"What are the speakers mainly discussing?","o":["Preparing for a new employee's arrival","Repairing a broken laptop","Planning a conference trip","Interviewing a back-end developer"],"a":0,"ev":[0],"vi":"Cả bài nói về laptop, tài khoản, thẻ ra vào cho Minh, người \"starts on Monday the third\". Bẫy: \"conference\" là nơi Alan đang đi."},{"q":"Why can't the man set up repository access yet?","o":["The laptop hasn't arrived","A manager must give permission","The email account isn't active","Security is closed until Monday"],"a":1,"ev":[3],"vi":"\"can't open up repository access until her manager approves it\" = cần quản lý phê duyệt. Bẫy: laptop đã đến, email đã hoạt động."},{"q":"What will the man probably do next?","o":["Install the development tools","Call Alan at the conference","Print an access badge","Send a request to Joanna"],"a":3,"ev":[7],"vi":"\"I'll send Joanna the request now\" – \"now\" = việc làm ngay. Bẫy: cài dev tools thì đến thứ Sáu mới xong."},{"q":"When will the new employee receive her badge?","o":["On Friday afternoon","On Wednesday","On Monday morning","Before her start date"],"a":2,"ev":[0,9],"vi":"\"at ten on her first day\" – ngày đầu là Monday the third, nên là sáng thứ Hai. Đây là câu suy luận kết hợp hai chi tiết."}],"ts":[0.4,8.37,16.88,19.47,31.35,36.73,41.62,47.43,54.12,57.55,65.25]},{"id":"p3-07","part":3,"level":1,"topic":"IT","title":"Rescheduling a client demo","title_vi":"Dời lịch demo cho khách hàng","speakers":{"A":"M-AU","B":"F-US"},"lines":[["A","Hi Jessica. The client in Chicago just emailed. They can't make the demo on Thursday."],["B","Oh, really? That's a shame, we were all set. Did they say why?"],["A","Their CEO wants to join, but she's traveling that day."],["B","OK, that makes sense. So when can they do it instead?"],["A","They suggested Friday at eight a.m., Chicago time."],["B","Hmm, that's nine p.m. for us. A bit late, but I can manage if it's only an hour."],["A","Me too. I'll send them a new calendar invite, then, and confirm the time on both sides."],["B","Great. Should we do a quick test run before the demo?"],["A","Good idea. How about Friday afternoon at two?"],["B","Works for me. I'll book a room and let the team know. We should also double-check that the demo data is up to date."]],"questions":[{"q":"Why is the demo being rescheduled?","o":["The product isn't ready","A room is unavailable","A client executive is traveling","The team is too busy"],"a":2,"ev":[2],"vi":"\"Their CEO ... she's traveling that day\" – CEO được diễn đạt lại là \"client executive\"."},{"q":"What time will the demo start for the speakers?","o":["At 8 a.m.","At 2 p.m.","At 4 p.m.","At 9 p.m."],"a":3,"ev":[5],"vi":"\"that's nine p.m. for us\". Bẫy: 8 a.m. là giờ Chicago, 2 p.m. là buổi chạy thử."},{"q":"What will the man do?","o":["Send a calendar invitation","Book a room","Call the CEO","Prepare some slides"],"a":0,"ev":[6],"vi":"\"I'll send them a new calendar invite\". Bẫy: đặt phòng là việc của người phụ nữ."},{"q":"What does the woman suggest?","o":["Cancelling the demo","Having a practice session","Inviting more clients","Moving the demo to Thursday"],"a":1,"ev":[7],"vi":"\"do a quick test run before the demo\" = buổi tập/chạy thử (practice session)."}],"ts":[0.4,7.41,14.82,19.21,24.9,29.33,36.84,43.75,49.08,53.42]},{"id":"p3-08","part":3,"level":2,"topic":"Finance","title":"Expense report rejected","title_vi":"Báo cáo chi phí bị từ chối","speakers":{"A":"F-US","B":"M-GB"},"lines":[["A","Hi, Peter? It's Nina from Finance. I'm calling about your expense report for the Singapore trip."],["B","Oh, hi Nina. Is there a problem?"],["A","I'm afraid it's been rejected. Two receipts are missing: the taxi from the airport and one hotel dinner."],["B","Ah, the taxi driver didn't give me one. But I should have the dinner receipt somewhere."],["A","OK. For the taxi, you can fill in a missing-receipt form, as long as it's under fifty dollars."],["B","It was about thirty-five, so that's fine."],["A","Great. Just send everything back to me by Wednesday."],["B","And when would I get paid?"],["A","If I get it by then, the money will go out with payroll on the twenty-fifth."],["B","That's a relief. Things are a bit tight this month."],["A","I understand. I'll keep an eye out for your email."]],"questions":[{"q":"Why was the man's report rejected?","o":["Some receipts were missing","It was submitted late","The hotel was too expensive","The trip was not approved"],"a":0,"ev":[2],"vi":"\"Two receipts are missing\" – thiếu hóa đơn."},{"q":"What can the man do about the taxi expense?","o":["Ask the driver for a copy","Claim it next month","Pay for it himself","Complete a form instead"],"a":3,"ev":[4],"vi":"\"you can fill in a missing-receipt form\" = điền mẫu đơn thay cho hóa đơn. Bẫy: \"driver\" có trong bài nhưng tài xế không đưa hóa đơn."},{"q":"When will the man be reimbursed?","o":["On Wednesday","On the twenty-fifth","Next month","In fifty days"],"a":1,"ev":[8],"vi":"\"the money will go out with payroll on the twenty-fifth\". Bẫy: Wednesday là hạn nộp lại giấy tờ."},{"q":"What does the man mean when he says, \"Things are a bit tight this month\"?","o":["He has a busy schedule","His deadline is very close","He is short of money","His hotel room was small"],"a":2,"ev":[9],"vi":"\"tight\" ở đây nói về tiền bạc = đang eo hẹp tài chính, nên anh ấy mừng vì sắp được hoàn tiền."}],"ts":[0.4,7.62,12.32,19.81,26.43,33.87,37.83,42.15,45.17,50.47,55.8]},{"id":"p3-09","part":3,"level":3,"topic":"Events","title":"Anniversary catering","title_vi":"Đặt tiệc kỷ niệm công ty","speakers":{"A":"M-US","B":"F-AU"},"lines":[["A","Hi, I'm calling from Brightline Software. We're celebrating our tenth anniversary on the twelfth of June, and we need catering."],["B","Congratulations! How many guests are you expecting?"],["A","We've invited a hundred and fifty, but we're planning for about a hundred and twenty."],["B","OK. Our buffet package is thirty-two dollars a head, and that includes drinks."],["A","Does it cover vegetarian options? About a third of our staff don't eat meat."],["B","Yes, and we can do vegan and gluten-free on request at no extra charge."],["A","Great. What about a cake? I'd like one with our logo on it."],["B","We can do that, but custom cakes need two weeks' notice, so we'd need the design by the twenty-ninth of May."],["A","That's cutting it close. Our designer's away until the twenty-fifth."],["B","That still leaves a few days. I'll email you a quote today, and a twenty percent deposit will lock in the date."]],"questions":[{"q":"What is the company celebrating?","o":["A product launch","A business milestone","A staff member's retirement","A new office opening"],"a":1,"ev":[0],"vi":"\"our tenth anniversary\" = kỷ niệm 10 năm, diễn đạt lại thành \"business milestone\"."},{"q":"How many people does the man expect to attend?","o":["About 32","About 150","About 120","About a third of the staff"],"a":2,"ev":[2],"vi":"\"invited a hundred and fifty, but we're planning for about a hundred and twenty\". Bẫy: 150 là số người được mời, 32 là giá mỗi suất."},{"q":"What does the woman say about special diets?","o":["They cost extra","They need two weeks' notice","They must be ordered by the 25th","They are available at no charge"],"a":3,"ev":[5],"vi":"\"vegan and gluten-free on request at no extra charge\" = miễn phí. Bẫy: \"two weeks' notice\" là cho bánh kem."},{"q":"What will the woman probably do next?","o":["Design a cake","Collect a deposit","Send a price quote","Call the designer"],"a":2,"ev":[9],"vi":"\"I'll email you a quote today\". Bẫy: deposit là việc khách phải làm sau đó, không phải việc tiếp theo của cô ấy."}],"ts":[0.4,9.49,15.11,20.72,28.21,33.99,40.49,45.6,53.66,58.99]},{"id":"p3-10","part":3,"level":1,"topic":"IT","title":"Server outage review","title_vi":"Họp rút kinh nghiệm sự cố máy chủ","speakers":{"A":"F-US","B":"M-AU","C":"F-GB"},"lines":[["A","OK, let's keep this short, we've all got a lot on today. Ben, can you walk us through what happened last night?"],["B","Sure. The main web server went down at about eleven fifteen and was offline for forty minutes."],["C","What caused it?"],["B","The disk got full. The old log files weren't being deleted, so they just kept growing."],["A","And how did we find out?"],["B","A customer emailed support. Our monitoring didn't send any alert."],["C","That's not good. We should've known before the customers did. That's the bigger issue here."],["A","Agreed. So, two actions. Ben, can you set up automatic log cleanup?"],["B","Sure, I'll have it done by Wednesday and test it on the staging server first."],["A","And Claire, could you add a disk space alert to our monitoring?"],["C","Leave it with me. I'll do it today."]],"questions":[{"q":"How long was the server offline?","o":["Eleven minutes","Fifteen minutes","About an hour","Forty minutes"],"a":3,"ev":[1],"vi":"\"offline for forty minutes\". Bẫy: \"eleven fifteen\" là thời điểm sập."},{"q":"What caused the problem?","o":["A power cut","Log files filled up the disk","A customer's mistake","A software update"],"a":1,"ev":[3],"vi":"\"The disk got full. The old log files weren't being deleted\" – log đầy ổ đĩa."},{"q":"How did the team learn about the outage?","o":["From a monitoring alert","From a server report","From a customer's message","From a manager's call"],"a":2,"ev":[5],"vi":"\"A customer emailed support\". Bẫy: monitoring KHÔNG gửi cảnh báo."},{"q":"What does Claire mean when she says, \"Leave it with me\"?","o":["She will handle the task","She wants to leave the meeting","She needs more information","She disagrees with the plan"],"a":0,"ev":[9,10],"vi":"\"Leave it with me\" = để tôi lo việc đó; cô ấy nhận làm cảnh báo dung lượng đĩa ngay hôm nay."}],"ts":[0.4,7.26,13.72,16.23,22.66,25.09,30.46,39.03,45.02,50.18,54.69]},{"id":"p3-11","part":3,"level":2,"topic":"HR","title":"Interview panel scheduling","title_vi":"Sắp xếp hội đồng phỏng vấn","speakers":{"A":"M-GB","B":"F-US"},"lines":[["A","Hi Laura. I'm putting together the interview panel for the senior developer role. Have you got a moment?"],["B","Sure, Greg. Who's on it so far?"],["A","Me, Hannah from the architecture team, and I'd like you to join as well."],["B","Happy to. When are the interviews?"],["A","We've got three candidates. I was thinking Tuesday the eighth, all afternoon."],["B","Ah, I've got a client workshop that day. Could we do Wednesday the ninth instead?"],["A","Let me check Hannah's calendar. She's free on the ninth, but only until three."],["B","So if each interview's an hour, we'd need to start at noon."],["A","That works. I'll book a room and send invites to the candidates today."],["B","Great. Could you also forward me their CVs? I'd like to prepare some technical questions."],["A","Will do. I'll send them over by the end of the day."]],"questions":[{"q":"What are the speakers mainly discussing?","o":["Arranging job interviews","Hiring a new architect","Planning a client workshop","Reviewing a candidate's code"],"a":0,"ev":[0],"vi":"\"putting together the interview panel for the senior developer role\" – sắp xếp phỏng vấn. Bẫy: \"architecture team\", \"client workshop\" chỉ là chi tiết phụ."},{"q":"Why can't the woman attend on Tuesday?","o":["Hannah is unavailable","She will be on vacation","She has a client workshop","The room is booked"],"a":2,"ev":[5],"vi":"\"I've got a client workshop that day\"."},{"q":"What time will the interviews probably start?","o":["At three","At noon","At nine","At one"],"a":1,"ev":[6,7],"vi":"\"we'd need to start at noon\" – ba buổi mỗi buổi 1 tiếng, kết thúc trước 3 giờ. Bẫy: three là giờ Hannah bận, nine là ngày 9."},{"q":"What does the woman ask the man to do?","o":["Book a meeting room","Prepare technical questions","Contact Hannah","Send her the candidates' résumés"],"a":3,"ev":[9],"vi":"\"forward me their CVs\" – CV = résumé. Bẫy: chuẩn bị câu hỏi là việc cô ấy tự làm."}],"ts":[0.4,9.04,13.96,19.62,24.01,30.75,37.49,44.21,48.79,55.03,63.5]},{"id":"p3-12","part":3,"level":3,"topic":"Office","title":"Moving to a new floor","title_vi":"Chuyển sang tầng mới","speakers":{"A":"F-AU","B":"M-US"},"lines":[["A","Hi Mike. Facilities just confirmed our move to the sixth floor. It's happening the weekend of the twentieth."],["B","Finally. Do we know the seating plan yet?"],["A","Roughly. The dev team gets the area by the windows, and QA's going next to the kitchen."],["B","QA won't be thrilled about that. How many desks are there?"],["A","Forty-two, which is four more than we need, so we've got some room to grow."],["B","Good. What about network ports? Last time, half of them didn't work."],["A","IT's testing every port on the Thursday before, the eighteenth."],["B","And the printer? We've only got the one on four."],["A","They're moving it up, but it won't be connected until Monday at eleven. So anyone who needs printouts for Monday morning should print them on Friday."],["B","Got it. I'll put that in my team update right away."],["A","Thanks. Oh, and packing crates arrive Wednesday; everything has to be labelled by Friday at five."]],"questions":[{"q":"When will the office move take place?","o":["The weekend of the twentieth","On Thursday the eighteenth","On Monday at eleven","On Wednesday"],"a":0,"ev":[0],"vi":"\"It's happening the weekend of the twentieth\". Bẫy: 18 là ngày kiểm tra cổng mạng, Wednesday là ngày thùng đến."},{"q":"What does the man mean when he says, \"QA won't be thrilled about that\"?","o":["QA asked to sit by the windows","QA will move first","QA hasn't been told yet","QA will likely be unhappy with their spot"],"a":3,"ev":[2,3],"vi":"\"won't be thrilled\" = sẽ không vui; QA bị xếp ngồi cạnh bếp."},{"q":"What problem did the man experience during a previous move?","o":["Many network ports didn't work","The printer was lost","There weren't enough desks","Packing crates arrived late"],"a":0,"ev":[5],"vi":"\"Last time, half of them didn't work\" – \"them\" = network ports. Bẫy: bàn hiện thừa 4 chỗ, không thiếu."},{"q":"What will the man probably do next?","o":["Test the network ports","Tell his team about the printing arrangements","Move the printer upstairs","Label his packing crates"],"a":1,"ev":[8,9],"vi":"\"I'll put that in my team update right away\" – \"that\" = lời khuyên in tài liệu trước vào thứ Sáu. Bẫy: test cổng mạng là việc của IT."}],"ts":[0.4,10.05,14.96,22.95,28.69,34.73,42.15,47.38,52.58,63.5,68.83]},{"id":"p3-13","part":3,"level":1,"topic":"Sales","title":"Volume discount","title_vi":"Thương lượng chiết khấu số lượng","speakers":{"A":"M-US","B":"F-GB"},"lines":[["A","Hi Fiona, thanks for taking my call. We're planning to order more monitors this quarter."],["B","Great to hear, Tom. How many are you thinking?"],["A","About two hundred. Your price is a hundred and eighty dollars each. Can you offer a discount for that volume?"],["B","For two hundred units, I can give you eight percent off."],["A","Hmm. To be honest, another supplier offered us ten percent for the same order."],["B","I see. If you order two hundred and fifty, I can match that."],["A","That's more than we need right now, and we don't have the storage space. Could you include free delivery instead?"],["B","OK. Eight percent plus free delivery. Deal?"],["A","That sounds fair. Can you send me the offer in writing?"],["B","Of course. I'll email it to you by tomorrow morning, and we can finalize it this week."]],"questions":[{"q":"What does the man want to buy?","o":["Laptops","Printers","Monitors","Office chairs"],"a":2,"ev":[0],"vi":"\"We're planning to order more monitors\"."},{"q":"How many items does the man plan to order?","o":["About 180","About 200","About 250","About 10"],"a":1,"ev":[2],"vi":"\"About two hundred\". Bẫy: 180 là đơn giá, 250 là số lượng để được giảm 10%."},{"q":"What do the speakers agree on?","o":["A ten percent discount","An order of 250 units","Free delivery only","Eight percent off with free delivery"],"a":3,"ev":[7,8],"vi":"\"Eight percent plus free delivery. Deal?\" – \"That sounds fair.\" Bẫy: 10% chỉ có khi đặt 250 chiếc."},{"q":"What will the woman do by tomorrow morning?","o":["Send a written offer","Deliver the monitors","Call another supplier","Visit the man's office"],"a":0,"ev":[8,9],"vi":"\"send me the offer in writing\" – \"I'll email it to you by tomorrow morning\"."}],"ts":[0.4,6.25,10.67,17.41,21.99,27.65,33.0,39.58,44.57,48.29]},{"id":"p3-14","part":3,"level":2,"topic":"IT","title":"Code review compromise","title_vi":"Thỏa hiệp khi review code","speakers":{"A":"M-US","B":"F-AU","C":"M-GB"},"lines":[["A","So, Sophie, about your pull request. I left a comment asking you to split the payment service into three smaller classes."],["B","Yeah, I saw it, Jake. Honestly, I think that's overkill for now. The class is only about three hundred lines."],["A","But it's going to grow. We're adding refunds next sprint."],["C","Can I jump in? I think you both have a point."],["B","Go on, David."],["C","Sophie, what if you merge it as it is, but put the refund logic in its own class when we build it?"],["B","I can live with that. It means I don't have to redo the tests before Friday's release."],["A","OK, fine by me, as long as we add a ticket so it doesn't get forgotten."],["C","Fair enough. Jake, can you create the ticket?"],["A","Sure, I'll do it right after this call and put it in next sprint."]],"questions":[{"q":"What are the speakers mainly discussing?","o":["How to structure some code","When to release a feature","Who should write the tests","How to fix a payment bug"],"a":0,"ev":[0,1],"vi":"Tranh luận về việc \"split the payment service into three smaller classes\" – cách tổ chức code. Bẫy: \"release\", \"tests\" chỉ là chi tiết phụ."},{"q":"Why does Jake want Sophie to change her code?","o":["The code has too many bugs","The class will get bigger soon","The tests are failing","Sophie asked for his help"],"a":1,"ev":[2],"vi":"\"it's going to grow. We're adding refunds next sprint\" = class sẽ to ra."},{"q":"What does the woman mean when she says, \"I can live with that\"?","o":["She needs more time","She is unhappy with the plan","She accepts the suggestion","She wants to rewrite the tests"],"a":2,"ev":[6],"vi":"\"I can live with that\" = tôi chấp nhận được, đồng ý với đề xuất của David."},{"q":"What will Jake do after the call?","o":["Release the feature","Run the tests again","Split the payment class","Create a task for next sprint"],"a":3,"ev":[8,9],"vi":"\"I'll do it right after this call and put it in next sprint\" – \"it\" = ticket, diễn đạt lại thành \"task\". Bẫy: tách class đã bị hoãn."}],"ts":[0.4,8.82,19.12,23.65,28.42,31.28,38.09,45.75,50.76,55.73]},{"id":"p3-15","part":3,"level":3,"topic":"Travel","title":"Changing flights","title_vi":"Đổi chuyến bay công tác","speakers":{"A":"F-US","B":"M-AU"},"lines":[["A","Hi, Liam. Bad news: the Tokyo client just moved our meeting from Thursday to Friday afternoon."],["B","Oh, great. Our return flight's on Friday at six p.m."],["A","Exactly. The meeting runs from two to five, so there's no way we'll make it to the airport."],["B","Right. Let me check the airline's site. There's one at ten on Saturday morning, or one at eleven-forty Friday night."],["A","And when does the late one get in?"],["B","Seven on Saturday morning. Either way, the change fee is a hundred and twenty dollars each."],["A","I'd rather skip the red-eye. Could we stay one more night at the hotel?"],["B","I'll check. Our hotel has rooms at a hundred and fifty a night."],["A","That's fine. Can you rebook the flights, and I'll extend the hotel?"],["B","Sure. I'll also give Finance a heads-up about the extra cost."]],"questions":[{"q":"Why do the speakers need to change their plans?","o":["Their flight was cancelled","A client meeting was rescheduled","The hotel is fully booked","The client ended the contract"],"a":1,"ev":[0],"vi":"\"the Tokyo client just moved our meeting from Thursday to Friday afternoon\" – cuộc họp bị dời."},{"q":"How much is the fee for changing each ticket?","o":["$120","$150","$240","$270"],"a":0,"ev":[5],"vi":"\"the change fee is a hundred and twenty dollars each\". Bẫy: 150 là giá phòng khách sạn mỗi đêm."},{"q":"What does the woman mean when she says, \"I'd rather skip the red-eye\"?","o":["She doesn't want an overnight flight","She is feeling unwell","She wants to cancel the meeting","She prefers a cheaper ticket"],"a":0,"ev":[3,6],"vi":"\"red-eye\" = chuyến bay đêm (chuyến 11:40 tối thứ Sáu); cô ấy muốn bay sáng thứ Bảy và ở thêm một đêm."},{"q":"What will the woman do?","o":["Rebook the flights","Contact Finance","Extend the hotel stay","Call the client"],"a":2,"ev":[8],"vi":"\"I'll extend the hotel\". Bẫy: đổi vé và báo Finance là việc của Liam."}],"ts":[0.4,8.73,13.79,21.18,29.55,32.72,39.1,45.0,49.92,55.99]},{"id":"p3-16","part":3,"level":1,"topic":"Sales","title":"Marketing plan for app launch","title_vi":"Kế hoạch marketing ra mắt ứng dụng","speakers":{"A":"M-US","B":"F-AU","C":"M-GB"},"lines":[["A","Okay, let's touch base on the launch of the SmartDesk app. It goes live on March 3rd, so we've got about five weeks."],["B","Right. I think we should start with social media ads. They worked really well for our last product."],["C","I agree, Priya. But I'd also like to send an email to our existing customers. We have about twenty thousand on the list."],["A","Good idea, Ethan. Who can write the email?"],["C","I can draft it this week, and the design team can add some images."],["B","What about a launch video? Customers love short demos."],["A","Sounds great, but the video agency needs at least three weeks, so we'd have to book them by Friday."],["B","No problem. I'll call the agency this afternoon and get a quote."],["A","Perfect. Let's meet again next Monday to make sure we're on track."]],"questions":[{"q":"What are the speakers mainly discussing?","o":["Hiring a new design team","Fixing problems with an app","Choosing a launch date","Ways to promote a new app"],"a":3,"ev":[0],"vi":"Câu mở đầu \"let's touch base on the launch of the SmartDesk app\" và cả bài bàn về quảng cáo, email, video → quảng bá ứng dụng mới. Ngày ra mắt (March 3rd) đã được chốt nên \"Choosing a launch date\" là bẫy."},{"q":"According to Ethan, how many customers are on the email list?","o":["About 5,000","About 20,000","About 3,000","About 2,000"],"a":1,"ev":[2],"vi":"Ethan nói \"We have about twenty thousand on the list\". Bẫy: \"five weeks\" và \"three weeks\" là số khác trong bài."},{"q":"What does Ethan offer to do?","o":["Write a message to customers","Add images to a design","Book a video agency","Run social media ads"],"a":0,"ev":[4],"vi":"\"I can draft it this week\" – draft = viết bản nháp email. Việc thêm hình là của design team, không phải Ethan."},{"q":"What will Priya probably do this afternoon?","o":["Film a product demo","Meet with the team","Ask an agency for a price","Email existing customers"],"a":2,"ev":[7],"vi":"Priya nói \"I'll call the agency this afternoon and get a quote\" – quote = báo giá, được diễn đạt lại thành \"ask for a price\". Cuộc họp là \"next Monday\"."}],"ts":[0.4,8.94,18.32,28.45,33.58,38.84,44.76,51.41,57.89]},{"id":"p3-17","part":3,"level":2,"topic":"Finance","title":"Q4 budget cut","title_vi":"Cắt giảm ngân sách Q4","speakers":{"A":"F-GB","B":"M-US","C":"F-AU"},"lines":[["A","Thanks for joining. I'm afraid I've got some bad news. The Q4 budget for the CRM upgrade has been cut by fifteen percent."],["B","Fifteen? Ouch. We were already running tight. What's driving that, Hannah?"],["A","Sales came in below forecast in Q3, so every department has to tighten its belt."],["C","Well, Carlos, we could postpone the mobile app integration. The sales team won't really use it until spring anyway."],["B","True, Mei, and that's where most of the licensing cost sits. What about the data migration?"],["C","We can't drop that. The old system's support contract ends on December 31st."],["A","Then the mobile piece is the obvious candidate. How much would that save?"],["B","Roughly forty thousand dollars, which more than covers the cut."],["A","Great. Can you put that in writing so I can take it to the finance director on Thursday?"],["B","Sure, I'll send you a revised plan first thing tomorrow."]],"questions":[{"q":"What does Carlos mean when he says, \"We were already running tight\"?","o":["The team was working late","The project had little money to spare","The deadline had already passed","The schedule was too relaxed"],"a":1,"ev":[1],"vi":"\"Running tight\" ở đây nói về ngân sách: vốn đã eo hẹp, giờ còn bị cắt 15%. Bẫy: hiểu \"tight\" là lịch trình/giờ làm."},{"q":"Why was the budget reduced?","o":["A support contract is ending","Licensing costs went up","Sales were lower than predicted","The project is behind schedule"],"a":2,"ev":[2],"vi":"Hannah: \"Sales came in below forecast in Q3\" → doanh số thấp hơn dự báo. \"Support contract ends\" là lý do không thể bỏ data migration, không phải lý do cắt ngân sách."},{"q":"How much would postponing the mobile integration save?","o":["About $15,000","About $31,000","About $4,000","About $40,000"],"a":3,"ev":[7],"vi":"Carlos: \"Roughly forty thousand dollars\". Bẫy: \"fifteen percent\" và \"December 31st\"."},{"q":"What does Carlos say he will do?","o":["Send an updated plan","Meet the finance director on Thursday","Cancel the data migration","Renew a support contract"],"a":0,"ev":[9],"vi":"\"I'll send you a revised plan first thing tomorrow\" – revised = updated. Gặp finance director vào thứ Năm là việc của Hannah."}],"ts":[0.4,10.17,15.78,22.35,32.02,38.57,46.08,51.94,56.35,62.97]},{"id":"p3-18","part":3,"level":3,"topic":"Service","title":"Damaged delivery","title_vi":"Hàng giao bị hư hỏng","speakers":{"A":"F-US","B":"M-AU"},"lines":[["A","Thanks for calling Brightline Home Goods, this is Sara. How can I help?"],["B","Hi, my name's Liam Doyle. I ordered a glass dining table, and it arrived this morning with a crack right across the top."],["A","Oh, I'm so sorry to hear that. Was the box itself damaged when it was delivered?"],["B","Yeah, one corner was crushed. Luckily, I took photos before I opened it."],["A","That's really helpful. If you email those to us, I can file a claim with the courier today."],["B","Fine, but I've got eight people coming for dinner on the twentieth. I can't exactly wait three weeks for a replacement."],["A","Understood. Normally replacements take ten business days, but our Leeds warehouse has that model in stock, so I can send one by express. It'd reach you on the eighteenth."],["B","That's cutting it close, but it works. And what about the broken one?"],["A","Our driver will collect it when he drops off the new table, so there's nothing you need to do."],["B","Great. Where should I send the photos?"],["A","I'll text you a link right after this call."]],"questions":[{"q":"Why is the man calling?","o":["His order has not been delivered","A product he bought arrived broken","He wants to cancel a dinner booking","He was charged the wrong amount"],"a":1,"ev":[1],"vi":"\"it arrived this morning with a crack right across the top\" → hàng đến bị nứt. Bẫy: \"dinner\" có trong bài nhưng là bữa tối ở nhà anh ấy."},{"q":"What does the man imply when he says, \"I can't exactly wait three weeks for a replacement\"?","o":["He needs the item before an event","He would prefer a full refund","He was promised delivery in three weeks","He will buy from another store"],"a":0,"ev":[5],"vi":"Ngay trước đó anh nói có 8 khách ăn tối ngày 20 → cần bàn trước sự kiện. Bẫy: \"three weeks\" không phải là thời hạn được hứa."},{"q":"When will the replacement most likely arrive?","o":["On the 20th","In ten business days","In three weeks","On the 18th"],"a":3,"ev":[6],"vi":"\"It'd reach you on the eighteenth\" (gửi express). Bẫy: \"twentieth\" là ngày bữa tối, \"ten business days\" là thời gian bình thường."},{"q":"What will the woman do after the call?","o":["Email photos of the damage","Visit the man's home","Text the man a way to send pictures","Issue a full refund"],"a":2,"ev":[9,10],"vi":"Liam hỏi gửi ảnh ở đâu, Sara trả lời \"I'll text you a link right after this call\". Gửi ảnh qua email là việc của người đàn ông."}],"ts":[0.4,5.53,13.81,19.62,25.88,31.93,39.72,51.36,56.57,62.42,66.02]},{"id":"p3-19","part":3,"level":1,"topic":"IT","title":"Weekend database migration","title_vi":"Di chuyển cơ sở dữ liệu cuối tuần","speakers":{"A":"M-GB","B":"F-US"},"lines":[["A","Lisa, have you got a minute? I want to plan the database migration."],["B","Sure, James. Are we still doing it this weekend?"],["A","Yes, on Saturday night. We'll start at 10 p.m., when traffic is lowest."],["B","How long will it take?"],["A","About six hours, if everything goes well. So we should finish by 4 a.m., well before anyone logs in on Sunday morning."],["B","OK. Who's going to be on call?"],["A","I'll take Saturday night, and Raj will cover Sunday in case anything breaks."],["B","I can be the backup on Saturday. I'll keep my phone on, so just call me if you need help. Do we have a rollback plan, too?"],["A","Yes, I wrote one last week. If something goes wrong, we can switch back to the old server in about thirty minutes. Oh, and could you give the customer support team a heads-up? They should know the system will be down."],["B","No problem. I'll email them this afternoon."]],"questions":[{"q":"What are the speakers planning?","o":["A team dinner on Saturday","A customer support training","A new software launch","Moving a database over the weekend"],"a":3,"ev":[0,1],"vi":"\"I want to plan the database migration\" ... \"this weekend\" → chuyển cơ sở dữ liệu cuối tuần."},{"q":"What time will the work start?","o":["At 4 a.m.","At 6 p.m.","At 10 p.m.","At 10 a.m."],"a":2,"ev":[2],"vi":"\"We'll start at 10 p.m.\" Bẫy: \"4 a.m.\" là giờ kết thúc, \"six hours\" là thời lượng."},{"q":"Who will be on call on Sunday?","o":["Raj","James","Lisa","A support manager"],"a":0,"ev":[6],"vi":"\"Raj will cover Sunday\". James trực tối thứ Bảy, Lisa là người dự phòng thứ Bảy."},{"q":"What will the woman probably do this afternoon?","o":["Call James for help","Inform another team about downtime","Start the migration","Write a rollback plan"],"a":1,"ev":[8,9],"vi":"James nhờ báo support team rằng hệ thống sẽ ngừng (\"will be down\"); Lisa: \"I'll email them this afternoon\"."}],"ts":[0.4,6.61,12.01,19.38,22.16,31.81,36.2,42.03,52.01,67.32]},{"id":"p3-20","part":3,"level":2,"topic":"HR","title":"Signing up for training","title_vi":"Đăng ký khóa đào tạo nội bộ","speakers":{"A":"F-AU","B":"M-US"},"lines":[["B","Hi Grace, I'd like to sign up for the project management course next month. Are there any seats left?"],["A","Let me check. The session on the 12th and 13th is fully booked, I'm afraid."],["B","Oh, that's a shame. Is there another one?"],["A","There's a second session on the 26th and 27th. It has four seats left."],["B","That should work. I'll need my manager's approval first, though, right?"],["A","Yes, she has to sign off on it. But I can hold a seat for you until Friday."],["B","Perfect. I'll talk to her this afternoon."],["A","Great. And just so you know, the course is in the Riverside building, not here at head office."],["B","Riverside? That's a bit of a trek from my place."],["A","It is, but there's a shuttle bus from the main entrance every thirty minutes."],["B","Good to know. Thanks, Grace."]],"questions":[{"q":"What does the man want to do?","o":["Book a meeting room","Teach a course","Enroll in a training program","Transfer to another office"],"a":2,"ev":[0],"vi":"\"I'd like to sign up for the project management course\" – sign up = enroll, course = training program."},{"q":"When does the available session begin?","o":["On the 26th","On the 12th","On the 13th","On Friday"],"a":0,"ev":[1,3],"vi":"Khóa 12–13 đã \"fully booked\"; khóa còn chỗ là \"the 26th and 27th\". Bẫy: \"Friday\" là hạn giữ chỗ."},{"q":"What does the woman offer to do?","o":["Approve the man's request","Reserve a place for a few days","Call the man's manager","Drive the man to Riverside"],"a":1,"ev":[5],"vi":"\"I can hold a seat for you until Friday\" – hold a seat = giữ chỗ. Việc duyệt (sign off) là của quản lý."},{"q":"What does the man mean when he says, \"That's a bit of a trek from my place\"?","o":["He prefers to work from home","He doesn't know the building","He will be late for the course","The location is far for him"],"a":3,"ev":[8],"vi":"\"A trek\" = một quãng đường dài, vất vả → địa điểm xa nhà anh. Grace đáp lại bằng thông tin xe đưa đón, xác nhận ý này."}],"ts":[0.4,8.49,15.56,20.43,27.82,34.42,41.6,46.39,54.22,59.47,65.44]},{"id":"p3-21","part":3,"level":3,"topic":"Legal","title":"Contract renewal on hold","title_vi":"Gia hạn hợp đồng chờ pháp chế","speakers":{"A":"M-US","B":"F-GB"},"lines":[["A","Olivia, quick question. Where are we with the Harlow Logistics renewal? Their current contract runs out on the 30th."],["B","I know, Kevin. I'm about two-thirds of the way through it, but there's a new liability clause in section 9 that I'm not comfortable with."],["A","What's the issue?"],["B","It caps their liability at fifty thousand, down from two hundred thousand in the old agreement. That shifts a lot of risk onto us."],["A","Hmm. Their account manager didn't mention that at all."],["B","They often don't. I'd like to push back before we sign anything."],["A","Fair enough, but if this slips past the 30th, we lose the discounted rate they offered."],["B","Then let's ask for a short extension. Could you get them to keep the old terms in place until mid-month?"],["A","I'll ring them this afternoon. Should I loop you in on the call?"],["B","Please do. It'll be quicker if I explain the clause myself."]],"questions":[{"q":"Why has the contract renewal been delayed?","o":["The supplier hasn't sent the contract","The legal team is understaffed","A term in the new draft is a concern","The discount offer has expired"],"a":2,"ev":[1],"vi":"Olivia: \"there's a new liability clause in section 9 that I'm not comfortable with\" – clause = term. Bẫy: ưu đãi chỉ mất NẾU trễ quá ngày 30, chưa hết hạn."},{"q":"What is the liability limit in the new agreement?","o":["$200,000","$30,000","$9,000","$50,000"],"a":3,"ev":[3],"vi":"\"It caps their liability at fifty thousand, down from two hundred thousand\". Bẫy: 200.000 là mức cũ; \"30th\" và \"section 9\" là số khác."},{"q":"According to the man, what will happen if the deadline is missed?","o":["A lower price will no longer be available","The old terms will stay in place","The liability cap will be raised","The account will be closed"],"a":0,"ev":[6],"vi":"\"we lose the discounted rate they offered\" → mất giá ưu đãi. \"Keep the old terms\" là điều họ định đề nghị, không phải hậu quả."},{"q":"What will the man probably do this afternoon?","o":["Review section 9 of the contract","Ask the other company for more time","Sign the renewal","Meet with the woman's manager"],"a":1,"ev":[7,8],"vi":"Olivia đề nghị xin gia hạn ngắn (\"ask for a short extension\"), Kevin: \"I'll ring them this afternoon\". Đọc section 9 là việc của Olivia."}],"ts":[0.4,10.45,21.11,23.65,34.54,39.94,46.42,52.73,61.13,66.86]},{"id":"p3-22","part":3,"level":1,"topic":"IT","title":"Company hackathon","title_vi":"Tổ chức hackathon công ty","speakers":{"A":"F-US","B":"M-AU","C":"M-GB"},"lines":[["A","So, the hackathon is on November 28th. Josh, did you find a venue?"],["B","Yeah. The big conference room on the fifth floor is too small, so I booked the event space at the Lakeside Hotel. It holds a hundred and fifty people."],["A","Great. How many people have signed up so far, Sam?"],["C","Eighty-four, and registration closes next Friday. Most people want to work in teams of four."],["A","Teams of four sounds good. What about prizes?"],["C","Management approved three thousand dollars. Maybe two thousand for first place and a thousand for second?"],["B","Hmm, that's a bit much for one team. Why not split it into three prizes?"],["A","Good point. Let's do fifteen hundred, one thousand, and five hundred."],["C","Sounds fair. I'll update the event page today."],["A","Thanks, Sam. And Josh, could you sort out food for the day?"],["B","Sure, I'll get some quotes from caterers."]],"questions":[{"q":"What are the speakers mainly discussing?","o":["Hiring new engineers","Arrangements for a company event","A client conference at a hotel","A software release date"],"a":1,"ev":[0],"vi":"Cả bài bàn về địa điểm, số người, giải thưởng, đồ ăn cho \"the hackathon\" → sự kiện công ty. Bẫy: \"hotel\" có trong bài nhưng không phải hội nghị khách hàng."},{"q":"Where will the hackathon take place?","o":["In a conference room","On the fifth floor","In the company cafeteria","At a hotel"],"a":3,"ev":[1],"vi":"\"I booked the event space at the Lakeside Hotel\". Phòng họp tầng 5 \"too small\" nên bị loại."},{"q":"What does Josh mean when he says, \"that's a bit much for one team\"?","o":["The teams are too big","The event is too expensive","One prize seems too large","There are too many teams"],"a":2,"ev":[6],"vi":"Josh phản hồi đề xuất $2.000 cho giải nhất và gợi ý chia thành 3 giải → giải đó quá lớn cho một đội."},{"q":"What will Josh probably do next?","o":["Contact catering companies","Update the event page","Book a hotel room","Approve the prize budget"],"a":0,"ev":[10],"vi":"\"I'll get some quotes from caterers\". Cập nhật trang sự kiện là việc của Sam."}],"ts":[0.4,5.99,15.54,19.71,27.94,31.85,39.75,45.79,51.84,56.97,61.75]},{"id":"p3-23","part":3,"level":2,"topic":"HR","title":"Hybrid work policy questions","title_vi":"Hỏi về chính sách làm việc kết hợp","speakers":{"A":"M-US","B":"F-AU"},"lines":[["A","Hi Chloe, got a sec? I've got a couple of questions about the new hybrid work policy."],["B","Sure, Mark. What do you want to know?"],["A","The email said three days a week in the office. Can I choose which days?"],["B","Mostly, yes. But everyone has to be in on Tuesdays for team meetings. You pick the other two."],["A","OK. And when does it actually start? I thought it was this month."],["B","It was supposed to, but the new desk booking system isn't ready yet, so it's been pushed to January 6th."],["A","Got it. What if I need to work from home on a Tuesday, say, for a delivery?"],["B","Just get your manager's OK at least a day in advance. It's fine once in a while."],["A","Makes sense. Is there a document with all of this?"],["B","There's an FAQ on the intranet. I'll send you the link after lunch."]],"questions":[{"q":"On which day must all employees be in the office?","o":["Monday","Thursday","Any day they choose","Tuesday"],"a":3,"ev":[3],"vi":"\"everyone has to be in on Tuesdays for team meetings\". Hai ngày còn lại mới được tự chọn."},{"q":"Why has the start of the policy been delayed?","o":["A reservation system isn't ready","Managers haven't approved it","The office is being renovated","Staff asked for more time"],"a":0,"ev":[5],"vi":"\"the new desk booking system isn't ready yet\" – booking system = reservation system."},{"q":"What must employees do to work from home on a Tuesday?","o":["Send an email to HR","Work an extra day later","Get approval a day ahead","Book a desk online"],"a":2,"ev":[7],"vi":"\"get your manager's OK at least a day in advance\" → xin phép trước một ngày. Bẫy: \"desk booking\" có trong bài nhưng nói về chuyện khác."},{"q":"What does the woman offer to do?","o":["Call the man's manager","Share a link to a document","Book a desk for the man","Update the FAQ"],"a":1,"ev":[9],"vi":"\"I'll send you the link after lunch\" (link tới FAQ trên intranet)."}],"ts":[0.4,7.19,11.84,17.34,26.86,32.14,40.18,46.3,54.02,58.32]},{"id":"p3-24","part":3,"level":3,"topic":"IT","title":"Client feedback on mockups","title_vi":"Phản hồi của khách về bản thiết kế","speakers":{"A":"F-GB","B":"M-US"},"lines":[["A","Ryan, I just got off a call with Northwind about the mockups. Overall they're happy, but they've flagged a few things."],["B","Uh-oh. Go on."],["A","First, the colour scheme. They think the dark blue feels a bit too corporate for a fitness app."],["B","Fair enough. I can try something brighter. Anything else?"],["A","The checkout flow. They'd like it cut from five screens to three."],["B","Three? That's doable, but I'd need to rethink the payment step entirely."],["A","I figured. They originally wanted the revision by Wednesday, but I told them Friday was more realistic."],["B","Friday the 14th? Honestly, given the checkout changes, Monday the 17th would be safer."],["A","Hmm, I've already committed to Friday. Could you send the new colours by Wednesday and the checkout by Friday?"],["B","OK, that I can manage. I'll share a draft palette with you tomorrow so you can check it first."]],"questions":[{"q":"What is the conversation mainly about?","o":["A fitness app's launch date","Changes a client has requested","A problem with a payment system","Hiring a new designer"],"a":1,"ev":[0],"vi":"\"they've flagged a few things\" rồi liệt kê màu sắc và checkout → yêu cầu chỉnh sửa của khách. Bẫy: \"payment step\" có trong bài nhưng không phải sự cố."},{"q":"How many screens does the client want in the checkout flow?","o":["Five","Fourteen","Three","Seventeen"],"a":2,"ev":[4],"vi":"\"cut from five screens to three\". Bẫy: 5 là số hiện tại; 14 và 17 là ngày tháng."},{"q":"What does the woman imply when she says, \"I've already committed to Friday\"?","o":["She doesn't want to change the deadline","She is busy on Monday","She has finished her part","The client prefers Wednesday"],"a":0,"ev":[7,8],"vi":"Ryan đề nghị dời sang thứ Hai 17; Emma đáp đã hứa với khách thứ Sáu → không muốn đổi hạn."},{"q":"What does the woman ask the man to do?","o":["Contact the client directly","Move the deadline to the 17th","Keep the dark blue colors","Deliver the work in two stages"],"a":3,"ev":[8],"vi":"\"send the new colours by Wednesday and the checkout by Friday\" → nộp thành hai phần. Bẫy: ngày 17 là đề xuất của Ryan và bị từ chối."}],"ts":[0.4,8.75,12.4,19.4,26.0,31.35,37.97,45.6,54.02,61.97]},{"id":"p3-25","part":3,"level":1,"topic":"Events","title":"Client dinner reservation","title_vi":"Đặt nhà hàng tiếp khách","speakers":{"A":"M-AU","B":"F-GB"},"lines":[["B","Good afternoon, Rosa's Kitchen. How can I help you?"],["A","Hi, I'd like to book a table for a client dinner this Thursday, please."],["B","Of course. For how many people?"],["A","Six. Around seven o'clock, if possible."],["B","Let me see. Seven is fully booked, but I can offer you seven thirty."],["A","Seven thirty is fine. Do you have a private room? We'll be talking business."],["B","Yes, we do. There's a small room upstairs that seats eight. There's a fifty-dollar booking fee for it, though."],["A","That's OK. Oh, and one of our guests is vegetarian."],["B","No problem. Our chef has a full vegetarian menu. Could I have a name and phone number for the booking?"],["A","Sure. It's Ben Carter, from Atlas Software. My number is 555-0142."],["B","Thank you, Mr. Carter. I'll send you a confirmation text shortly."]],"questions":[{"q":"Why is the man calling?","o":["To order food for an office","To make a dinner reservation","To cancel a booking","To complain about a meal"],"a":1,"ev":[1],"vi":"\"I'd like to book a table for a client dinner\" – book a table = make a reservation."},{"q":"What time will the dinner start?","o":["At 7:00","At 6:00","At 8:00","At 7:30"],"a":3,"ev":[4,5],"vi":"7 giờ đã kín chỗ; nhà hàng đề nghị \"seven thirty\" và anh đồng ý. Bẫy: \"seven o'clock\" là giờ anh muốn ban đầu; 6 và 8 là số người/số ghế."},{"q":"What does the man mention about one of the guests?","o":["The guest will arrive late","The guest works at Atlas Software","The guest does not eat meat","The guest needs a private room"],"a":2,"ev":[7],"vi":"\"one of our guests is vegetarian\" → không ăn thịt. Atlas Software là công ty của Ben."},{"q":"What will the woman do next?","o":["Send a text message","Call the chef","Email a menu","Call the man back"],"a":0,"ev":[10],"vi":"\"I'll send you a confirmation text shortly\"."}],"ts":[0.4,6.21,11.41,15.92,20.19,26.86,33.36,43.06,48.07,57.43,65.61]},{"id":"p3-26","part":3,"level":2,"topic":"Logistics","title":"Stock shortage before big order","title_vi":"Thiếu hàng trước đơn lớn","speakers":{"A":"M-GB","B":"F-US"},"lines":[["B","Oliver, I need a quick update. Are we set for the Kenton order? They want twelve hundred units shipped by the 22nd."],["A","Not quite, Dana. I ran the count this morning, and we've only got about nine hundred in stock."],["B","Nine hundred? The system showed fifteen hundred last week."],["A","I know. It turns out a batch of three hundred was damaged in the flood at the Dover site, and nobody updated the records."],["B","That's not ideal. Can the factory make up the difference in time?"],["A","I called them. They can do it, but not until the 25th."],["B","That's three days late. Kenton won't be happy."],["A","What if we send the nine hundred on time and the rest as a second shipment? We'd cover the extra shipping cost."],["B","That might fly. I'll run it by their buyer and get back to you by end of day."]],"questions":[{"q":"How many units are currently in stock?","o":["1,200","1,500","300","About 900"],"a":3,"ev":[1],"vi":"\"we've only got about nine hundred in stock\". Bẫy: 1.200 là số khách đặt, 1.500 là số hệ thống hiển thị, 300 là lô bị hỏng."},{"q":"Why was the inventory record wrong?","o":["Damaged goods were not removed from it","The customer changed its order","The factory sent too many units","Last week's count was skipped"],"a":0,"ev":[3],"vi":"\"a batch of three hundred was damaged ... and nobody updated the records\" → hàng hỏng chưa được trừ khỏi hệ thống."},{"q":"What does the woman mean when she says, \"That might fly\"?","o":["The goods could be sent by air","The idea may be acceptable","The shipment may arrive early","The cost seems too high"],"a":1,"ev":[8],"vi":"\"That might fly\" = ý đó có thể được chấp nhận. Bẫy nghĩa đen \"fly\" = gửi bằng máy bay."},{"q":"What will the woman probably do next?","o":["Visit the Dover site","Call the factory","Discuss a plan with the customer","Count the stock again"],"a":2,"ev":[8],"vi":"\"I'll run it by their buyer\" – run it by = hỏi ý kiến người mua của Kenton. Gọi nhà máy là việc Oliver đã làm."}],"ts":[0.4,8.46,16.33,21.2,30.22,34.88,40.68,44.79,52.82]},{"id":"p3-27","part":3,"level":3,"topic":"IT","title":"Reporting a phishing email","title_vi":"Báo cáo email lừa đảo","speakers":{"A":"F-AU","B":"M-US"},"lines":[["A","Hi, is this IT security? I think I may have received a phishing email."],["B","You've come to the right place. What made you suspicious?"],["A","It looked like it came from our payroll provider, asking me to confirm my bank details by Friday or my salary would be delayed. But the sender's address ended in dot-co instead of dot-com."],["B","Good catch. Did you click the link or download anything?"],["A","I clicked the link, but as soon as the login page came up, something felt off, so I closed it. I didn't type anything in."],["B","OK, that's reassuring. Still, to be on the safe side, I'll need you to change your password within the next hour."],["A","Sure. Should I delete the email?"],["B","Not yet. And please don't forward it. Use the 'Report phishing' button in Outlook instead. That sends us the full message headers."],["A","Will do. Has anyone else gotten it?"],["B","You're the third person this morning, so I'll send a company-wide alert shortly."]],"questions":[{"q":"Why did the woman become suspicious of the email?","o":["It asked for her password","It arrived on a Friday","Her salary was delayed","The sender's address looked slightly wrong"],"a":3,"ev":[2],"vi":"\"the sender's address ended in dot-co instead of dot-com\". Bẫy: \"Friday\" và \"salary would be delayed\" là nội dung đe dọa trong email, không phải lý do cô nghi ngờ."},{"q":"What does the woman say she did?","o":["She deleted the message","She opened a page but entered nothing","She replied to the sender","She updated her bank details"],"a":1,"ev":[4],"vi":"\"I clicked the link ... so I closed it. I didn't type anything in.\" Cô hỏi có nên xóa nhưng chưa xóa."},{"q":"How soon must the woman change her password?","o":["By Friday","Within three hours","Within 60 minutes","By tomorrow morning"],"a":2,"ev":[5],"vi":"\"change your password within the next hour\" = trong 60 phút. Bẫy: \"Friday\" là hạn trong email lừa đảo, \"third\" là số người báo cáo."},{"q":"What will the man probably do next?","o":["Warn all employees","Reset the woman's password","Contact the payroll provider","Check the woman's computer"],"a":0,"ev":[9],"vi":"\"I'll send a company-wide alert shortly\" → cảnh báo toàn công ty. Đổi mật khẩu là việc người phụ nữ phải làm."}],"ts":[0.4,7.53,11.84,25.21,29.55,39.41,47.38,51.99,61.63,66.48]},{"id":"p3-28","part":3,"level":1,"topic":"Finance","title":"Report numbers don't match","title_vi":"Số liệu báo cáo quý không khớp","speakers":{"A":"F-US","B":"M-GB","C":"F-AU"},"lines":[["A","Paul, Zoe, thanks for coming. I found a problem in the quarterly report before it goes to the board."],["B","What kind of problem, Karen?"],["A","The total revenue on page two says four point two million, but the table on page five says four point five million."],["C","Oh no. I think I know why. The sales team sent us updated figures last Tuesday."],["B","And only one page was updated?"],["C","Probably. I changed the table, but I may have missed the summary."],["A","OK. Which number is correct?"],["C","The four point five million. But I'll double-check with sales to be sure."],["B","When does the report have to be ready?"],["A","The board meeting is on Thursday, so we need the final version by Wednesday at noon."],["B","No sweat. I'll check the other pages for the same mistake."]],"questions":[{"q":"What problem does Karen mention?","o":["A report was sent too late","Sales were lower than expected","A page is missing from the report","Two figures in a report are different"],"a":3,"ev":[2],"vi":"Trang 2 ghi 4,2 triệu nhưng bảng trang 5 ghi 4,5 triệu → hai con số không khớp."},{"q":"What does Zoe say she will do?","o":["Rewrite page five","Present the report to the board","Confirm a figure with another team","Check the other pages"],"a":2,"ev":[7],"vi":"\"I'll double-check with sales to be sure\". Kiểm tra các trang khác là việc của Paul."},{"q":"When is the final version due?","o":["Wednesday at noon","Thursday at noon","Last Tuesday","Thursday morning"],"a":0,"ev":[9],"vi":"\"we need the final version by Wednesday at noon\". Bẫy: thứ Năm là ngày họp hội đồng, thứ Ba là ngày sales gửi số liệu."},{"q":"What does Paul mean when he says, \"No sweat\"?","o":["He is not worried about the board","The task will be easy for him","He needs more time","The office is too hot"],"a":1,"ev":[10],"vi":"\"No sweat\" = không vấn đề gì, dễ thôi; anh nhận kiểm tra các trang khác. Bẫy nghĩa đen \"sweat\" = mồ hôi."}],"ts":[0.4,8.46,11.89,20.29,29.17,32.57,38.69,43.03,49.63,52.89,58.84]},{"id":"p3-29","part":3,"level":2,"topic":"HR","title":"Scheduling performance reviews","title_vi":"Sắp xếp buổi đánh giá hiệu suất","speakers":{"A":"F-GB","B":"M-AU"},"lines":[["A","Hi Nathan, I need to set up performance reviews for my team. HR wants them done by the end of the month, right?"],["B","Actually, Sophie, the deadline's been brought forward to the 24th, because payroll needs the ratings for the January pay raises."],["A","Oh, I hadn't heard that. That only gives me two weeks, and I've got seven people to see."],["B","Each meeting should take about forty-five minutes. Want me to book them for you?"],["A","That'd be a huge help. Could you avoid Mondays? I'm in client meetings all day."],["B","Sure. I'll spread them over Tuesday to Thursday. And remember, each person needs to submit a self-assessment beforehand."],["A","Where do they do that?"],["B","In the HR portal, under 'Reviews'. I'll send everyone a reminder with the link."],["A","Thanks. Oh, and can you book room 4B? It's quieter than the others."],["B","I'll check if it's free and send you the calendar invites by tomorrow."]],"questions":[{"q":"When must the reviews be completed?","o":["By the end of the month","By the 24th","By early January","By next Monday"],"a":1,"ev":[1],"vi":"\"the deadline's been brought forward to the 24th\". Bẫy: \"end of the month\" là hạn cũ Sophie tưởng; January là thời điểm tăng lương."},{"q":"Why was the deadline changed?","o":["The manager will be away","The team has grown","HR is changing its software","Pay decisions depend on the results"],"a":3,"ev":[1],"vi":"\"payroll needs the ratings for the January pay raises\" → kết quả đánh giá dùng để quyết định tăng lương."},{"q":"What does the man offer to do?","o":["Schedule the meetings","Write the self-assessments","Lead the reviews","Contact the payroll team"],"a":0,"ev":[3],"vi":"\"Want me to book them for you?\" – book = sắp lịch các buổi gặp."},{"q":"Why does the woman ask for room 4B?","o":["It is near her office","It is the largest room","It is less noisy","It has video equipment"],"a":2,"ev":[8],"vi":"\"It's quieter than the others\" = ít ồn hơn."}],"ts":[0.4,9.81,18.01,26.17,31.69,40.33,49.25,52.01,58.73,66.6]},{"id":"p3-30","part":3,"level":3,"topic":"Events","title":"Trade show booth setup","title_vi":"Chuẩn bị gian hàng hội chợ","speakers":{"A":"M-US","B":"F-GB"},"lines":[["A","Amelia, the TechConnect conference is three weeks away. Where are we with the booth?"],["B","We've got space 214, right by the main entrance. It's smaller than last year's, three by three metres instead of three by six, but the foot traffic should be much better."],["A","Good trade-off. What about the display screens?"],["B","The rental company quoted eighteen hundred for two screens, which is over budget. I'm waiting on a second quote that's due Wednesday."],["A","OK. And the banners?"],["B","That's the bottleneck. The printer needs final artwork ten days before the event, and marketing still hasn't signed off on the new logo."],["A","Seriously? That's been on their desk for two weeks."],["B","I know. I've chased them twice."],["A","Let me have a word with Diane, their director. She owes me one."],["B","That'd be great. If we can get approval by Friday, we're still on track."]],"questions":[{"q":"What does the woman say about the booth's location?","o":["It is larger than last year's","It should attract more visitors","It is far from the entrance","It costs eighteen hundred dollars"],"a":1,"ev":[1],"vi":"\"the foot traffic should be much better\" → nhiều khách đi qua hơn. Bẫy: gian hàng NHỎ hơn năm ngoái; 1.800 là giá thuê màn hình."},{"q":"Why might the banners be delayed?","o":["The printer is ten days behind","A second quote is due Wednesday","The booth is too small","A design has not been approved"],"a":3,"ev":[5],"vi":"\"marketing still hasn't signed off on the new logo\" → thiết kế chưa được duyệt. \"ten days\" là thời hạn của nhà in, không phải sự chậm trễ."},{"q":"What does the man offer to do?","o":["Call the printer","Get a second quote","Speak with a department head","Redesign the logo"],"a":2,"ev":[8],"vi":"\"Let me have a word with Diane, their director\" – director của marketing = trưởng bộ phận. Lấy báo giá thứ hai là việc Amelia đang chờ."},{"q":"By when is approval needed to stay on schedule?","o":["By Friday","By Wednesday","In ten days","In three weeks"],"a":0,"ev":[9],"vi":"\"If we can get approval by Friday, we're still on track\". Bẫy: Wednesday là hạn báo giá, ten days/three weeks là các mốc khác."}],"ts":[0.4,7.38,21.52,26.63,36.85,40.95,51.58,56.91,61.32,67.53]},{"id":"p4-01","part":4,"level":1,"topic":"Finance","title":"Late invoice payment","title_vi":"Thanh toán hóa đơn bị trễ","speakers":{"A":"F-US"},"lines":[["A","Hi, this message is for Daniel Park in the accounts team. This is Rachel Moore from Brightline Retail."],["A","I'm calling about invoice number 4471, which your company sent us on March third."],["A","I just wanted to give you a heads-up that our payment is going to be a little late this month."],["A","We're switching to a new accounting system, and all of our payments have been on hold since Monday."],["A","Our finance director has assured me that everything should be up and running again by next Wednesday."],["A","So you can expect the full amount, about twelve thousand dollars, by the end of next week."],["A","I know this isn't ideal, and I'm really sorry for the inconvenience."],["A","Believe me, we're as frustrated as you are."],["A","In the meantime, could you send me a copy of the invoice by e-mail?"],["A","Our new system needs a digital version, and I can't seem to find the original."],["A","You can reach me at 555-0193 if you have any questions."],["A","Thanks so much, Daniel, and talk to you soon."]],"questions":[{"q":"What is the purpose of the message?","o":["To request a discount on an invoice","To explain a late payment","To place a new order","To complain about a product"],"a":1,"ev":[2],"vi":"Câu \"give you a heads-up that our payment is going to be a little late\" cho thấy mục đích là báo thanh toán bị trễ. Bẫy: có nhắc \"invoice\" nhưng không xin giảm giá."},{"q":"Why has the payment been delayed?","o":["A manager is on vacation","An invoice contained an error","The company is changing its accounting system","The bank was closed on Monday"],"a":2,"ev":[3],"vi":"\"We're switching to a new accounting system\" = đổi hệ thống kế toán. Bẫy: \"Monday\" có xuất hiện nhưng là ngày bắt đầu tạm dừng thanh toán, không phải ngân hàng đóng cửa."},{"q":"Why does the speaker say, \"Believe me, we're as frustrated as you are\"?","o":["To show she understands the listener's situation","To complain about her finance director","To ask for an extra month to pay","To deny that the invoice was received"],"a":0,"ev":[6,7],"vi":"Sau lời xin lỗi \"I'm really sorry for the inconvenience\", câu này thể hiện sự đồng cảm với người nghe. Bẫy: \"finance director\" có trong bài nhưng cô không phàn nàn về ông ấy."},{"q":"What does the speaker ask the listener to do?","o":["Call the finance director","Visit her office next Wednesday","Correct the invoice amount","Send an electronic copy of a document"],"a":3,"ev":[8,9],"vi":"\"could you send me a copy of the invoice by e-mail?\" = gửi bản điện tử của hóa đơn. Bẫy: \"next Wednesday\" là ngày hệ thống chạy lại, không phải hẹn gặp."}],"ts":[0.4,8.31,14.83,20.36,26.62,32.87,39.24,44.25,47.91,52.63,58.04,64.35]},{"id":"p4-02","part":4,"level":2,"topic":"IT","title":"Weekend system maintenance","title_vi":"Bảo trì hệ thống cuối tuần","speakers":{"A":"M-GB"},"lines":[["A","Good afternoon, everyone. This is Tom from the IT operations team with a quick announcement."],["A","This Saturday, we'll be carrying out planned maintenance on our main database servers."],["A","The work will start at ten p.m. on Saturday and should be finished by six a.m. on Sunday."],["A","During that time, the customer portal and the internal HR system will be unavailable."],["A","E-mail and chat won't be affected, so you can still contact each other as usual."],["A","If you're on call this weekend, please note that alerts will be paused for the duration of the maintenance."],["A","Before you leave on Friday, make sure you save any open work and log out of all internal tools."],["A","Anything left unsaved may be lost when the servers restart."],["A","We'll send a confirmation e-mail as soon as everything is back online."],["A","And if you notice any problems on Sunday morning, please submit a ticket through the help desk rather than messaging the team directly."],["A","That way, we can track and prioritize issues more efficiently."],["A","Thanks for your patience, and have a great weekend."]],"questions":[{"q":"Who most likely is the speaker?","o":["A customer service agent","A human resources manager","A database vendor","An IT staff member"],"a":3,"ev":[0],"vi":"\"This is Tom from the IT operations team\" → nhân viên IT. Bẫy: \"HR system\" và \"database\" có trong bài nhưng không nói về nghề của người nói."},{"q":"When will the maintenance be completed?","o":["At ten p.m. on Friday","At ten p.m. on Saturday","At six a.m. on Sunday","On Sunday afternoon"],"a":2,"ev":[2],"vi":"\"should be finished by six a.m. on Sunday\". Bẫy: \"ten p.m. on Saturday\" là giờ bắt đầu, không phải giờ kết thúc."},{"q":"What will still be available during the maintenance?","o":["Messaging tools","The customer portal","The HR system","On-call alerts"],"a":0,"ev":[4],"vi":"\"E-mail and chat won't be affected\" → công cụ nhắn tin vẫn dùng được (paraphrase). Bẫy: portal, HR system không dùng được; alerts \"will be paused\"."},{"q":"What are listeners asked to do before leaving on Friday?","o":["Submit a help desk ticket","Restart their computers","Save their work and log out","Contact the on-call team"],"a":2,"ev":[6],"vi":"\"save any open work and log out of all internal tools\". Bẫy: \"submit a ticket\" là việc làm nếu có lỗi sáng Chủ nhật."}],"ts":[0.4,7.69,13.6,19.79,25.73,31.41,37.88,44.49,49.02,54.09,61.96,66.82]},{"id":"p4-03","part":4,"level":3,"topic":"IT","title":"Daily stand-up update","title_vi":"Cập nhật họp stand-up hằng ngày","speakers":{"A":"F-AU"},"lines":[["A","Morning, everyone. Let's keep this quick, since a few of us have the client demo at ten thirty."],["A","Yesterday, we closed out eleven of the fourteen tickets in the sprint backlog, so only three are still open, and we're in pretty good shape."],["A","Those three are all related to the payment module."],["A","Minh found the root cause of the checkout bug last night, so that fix should be merged by noon."],["A","The bad news is that the staging server went down again at around two a.m."],["A","Operations says it's a disk space issue and they're on it, but they can't give us an exact time."],["A","So, if you were planning to test on staging this morning, you might want to hold off."],["A","Use your local environment for now, and I'll post in the team channel once it's back."],["A","One more thing: the sprint review has been pushed from Thursday to Friday at three, because the product owner is traveling."],["A","That actually gives us an extra day, which we definitely need."],["A","If anyone's blocked, grab me right after this call rather than waiting until the afternoon."],["A","Okay, that's it from me. Over to you, Minh."]],"questions":[{"q":"What is the speaker mainly doing?","o":["Giving her team a progress update","Presenting a product to a client","Reviewing a product owner's plan","Reporting a server problem to operations"],"a":0,"ev":[0,1],"vi":"Đây là buổi stand-up: \"we closed out eleven of the fourteen tickets...\" → cập nhật tiến độ cho nhóm. Bẫy: \"client demo\" diễn ra lúc 10:30, không phải bây giờ."},{"q":"How many tickets are still unfinished?","o":["Two","Three","Eleven","Fourteen"],"a":1,"ev":[1,2],"vi":"Người nói: \"only three are still open\" → còn 3 ticket. Bẫy: 11 (đã xong) và 14 (tổng) cũng được nghe thấy."},{"q":"Why does the speaker say, \"you might want to hold off\"?","o":["To ask staff to postpone merging a fix","To recommend waiting until the demo ends","To warn that the product owner is unavailable","To advise against using a system that is down"],"a":3,"ev":[4,6],"vi":"Staging server \"went down\" nên cô khuyên đừng test trên staging lúc này. Bẫy: \"merged by noon\" và \"product owner is traveling\" là thông tin khác."},{"q":"What will most likely happen next?","o":["Another team member will speak","The client demo will begin","The sprint review will start","A server will be restarted"],"a":0,"ev":[11],"vi":"\"Over to you, Minh\" → Minh (đồng nghiệp) sẽ nói tiếp. Bẫy: sprint review đã dời sang thứ Sáu lúc 3 giờ, demo lúc 10:30."}],"ts":[0.4,8.72,18.28,22.62,29.42,35.82,42.68,48.86,55.14,63.48,68.41,75.03]},{"id":"p4-04","part":4,"level":1,"topic":"HR","title":"New engineering manager","title_vi":"Giới thiệu quản lý kỹ thuật mới","speakers":{"A":"M-US"},"lines":[["A","Okay, everyone, before we get started, I'd like to introduce a new member of our team."],["A","This is Priya Sharma, who's joining us as our new engineering manager."],["A","Priya comes to us from Nexora, where she led a team of twenty developers for six years."],["A","She has a lot of experience with cloud infrastructure and mobile apps, which is exactly what we need right now."],["A","Starting next Monday, Priya will be in charge of both the backend team and the mobile team."],["A","So going forward, please send your weekly reports to her instead of me."],["A","I'll still be around, of course, but I'll be focusing on our new partnership projects."],["A","Priya would like to meet each of you individually over the next two weeks."],["A","She'll send out calendar invitations later today, so please accept one that works for you."],["A","Also, we're having a small welcome lunch for her this Friday at the Italian place across the street."],["A","Lunch is on the company, so I hope everyone can make it."],["A","Now, Priya, would you like to say a few words?"]],"questions":[{"q":"What is the purpose of the talk?","o":["To announce a company merger","To describe a new mobile app","To introduce a new colleague","To explain a reporting system"],"a":2,"ev":[0,1],"vi":"\"I'd like to introduce a new member of our team\" → giới thiệu đồng nghiệp mới. Bẫy: \"mobile apps\", \"weekly reports\" chỉ là chi tiết phụ."},{"q":"How long did Priya work at Nexora?","o":["Two weeks","Six years","Twenty years","One month"],"a":1,"ev":[2],"vi":"\"led a team of twenty developers for six years\". Bẫy: \"twenty\" là số lập trình viên, \"two weeks\" là thời gian gặp riêng từng người."},{"q":"What are listeners asked to do going forward?","o":["Send their weekly reports to Priya","Join the mobile team","Prepare a short speech","Contact Nexora's developers"],"a":0,"ev":[5],"vi":"\"going forward, please send your weekly reports to her instead of me\". Bẫy: \"say a few words\" là việc Priya được mời làm, không phải người nghe."},{"q":"What will happen on Friday?","o":["Priya will start her new role","Calendar invitations will be sent","Individual meetings will end","The team will eat together"],"a":3,"ev":[9],"vi":"\"a small welcome lunch for her this Friday\" → cả nhóm ăn trưa cùng nhau. Bẫy: Priya bắt đầu phụ trách từ \"next Monday\"; lời mời lịch gửi \"later today\"."}],"ts":[0.4,7.18,12.24,18.32,25.15,31.38,36.46,42.09,46.83,52.89,59.03,63.03]},{"id":"p4-05","part":4,"level":2,"topic":"Travel","title":"Gate change and delay","title_vi":"Đổi cổng và hoãn chuyến bay","speakers":{"A":"F-GB"},"lines":[["A","Attention, please. This is an announcement for passengers on Skyways flight 382 to Singapore."],["A","Due to a technical issue with the aircraft, this flight has been delayed."],["A","The new departure time is eleven forty-five, about ninety minutes later than scheduled."],["A","In addition, the flight will now depart from gate 27 instead of gate 12."],["A","Gate 27 is in Terminal B, so please allow about fifteen minutes to walk there."],["A","Boarding is expected to begin at eleven ten."],["A","We know this isn't the news you were hoping for."],["A","To make up for the inconvenience, passengers can collect a meal voucher worth fifteen dollars at the Skyways service desk."],["A","Please have your boarding pass ready when you pick it up."],["A","If you have a connecting flight in Singapore, our staff at the desk can help you rebook it if necessary."],["A","We'll make further announcements if anything changes."],["A","Thank you for your patience, and we apologize for the delay."]],"questions":[{"q":"Where is the announcement being made?","o":["At a train station","At an airport","On an airplane","At a travel agency"],"a":1,"ev":[0,3],"vi":"\"passengers on Skyways flight 382\", \"depart from gate 27\" → thông báo ở sân bay. Bẫy: \"On an airplane\" sai vì hành khách chưa lên máy bay."},{"q":"Where will the flight now depart from?","o":["Gate 12","The service desk","Gate 15","A gate in Terminal B"],"a":3,"ev":[3,4],"vi":"\"depart from gate 27 instead of gate 12. Gate 27 is in Terminal B\". Bẫy: gate 12 là cổng cũ; \"fifteen\" là số phút đi bộ."},{"q":"Why does the speaker say, \"We know this isn't the news you were hoping for\"?","o":["To acknowledge passengers' disappointment","To announce that the flight is cancelled","To report a change of destination","To ask passengers to board quickly"],"a":0,"ev":[6],"vi":"Sau khi báo hoãn chuyến và đổi cổng, câu này thừa nhận hành khách thất vọng. Bẫy: chuyến bay chỉ bị hoãn, không bị hủy."},{"q":"What should passengers bring to collect a voucher?","o":["Their passport","A receipt","Fifteen dollars","Their boarding pass"],"a":3,"ev":[7,8],"vi":"\"Please have your boarding pass ready when you pick it up\". Bẫy: \"fifteen dollars\" là giá trị phiếu ăn, không phải tiền phải mang."}],"ts":[0.4,8.21,13.39,19.57,25.44,31.6,35.55,38.97,46.9,50.69,57.28,61.11]},{"id":"p4-06","part":4,"level":3,"topic":"Business","title":"Tech firm opens Asian office","title_vi":"Công ty công nghệ mở văn phòng ở châu Á","speakers":{"A":"M-AU"},"lines":[["A","In business news today, Seattle-based software company Cloudvane has announced plans to open its first Asian office in Ho Chi Minh City."],["A","The office, which will be located in the city's new technology park, is scheduled to open in September."],["A","Cloudvane says it will hire around three hundred engineers there by the end of next year, and that number could double by 2028."],["A","The company had originally considered Singapore and Bangkok, but chose Vietnam because of its large pool of young software developers."],["A","Chief executive Laura Bennett said the move would allow the company to provide round-the-clock support to customers in different time zones."],["A","However, not everyone is convinced."],["A","Some analysts point out that competition for experienced engineers in the region is already intense."],["A","Salaries for senior developers have risen by nearly twenty percent over the past two years."],["A","Still, Cloudvane's shares rose four percent after the announcement."],["A","The company plans to hold a recruitment event in the city in July, ahead of the opening."],["A","Ms. Bennett will also meet with local university leaders to discuss internship programs."],["A","Coming up after the break, we'll have the latest on the housing market."]],"questions":[{"q":"What is the news report mainly about?","o":["A company's expansion overseas","A merger between two software firms","Rising salaries in Singapore","A new university program"],"a":0,"ev":[0],"vi":"\"open its first Asian office in Ho Chi Minh City\" → mở rộng ra nước ngoài (paraphrase). Bẫy: Singapore và internship programs chỉ là chi tiết phụ."},{"q":"Why did Cloudvane choose Vietnam?","o":["Office rents are lower there","It has many available developers","It is close to its customers","The government offered tax benefits"],"a":1,"ev":[3],"vi":"\"because of its large pool of young software developers\" = có nhiều lập trình viên. Bẫy: \"customers in different time zones\" là lợi ích của việc hỗ trợ 24/7, không phải lý do chọn Việt Nam."},{"q":"Why does the speaker say, \"not everyone is convinced\"?","o":["To report that shareholders rejected the plan","To suggest that the opening will be delayed","To indicate that some experts have doubts","To show that local officials oppose the project"],"a":2,"ev":[5,6],"vi":"Câu tiếp theo \"Some analysts point out that competition... is already intense\" → một số chuyên gia nghi ngờ. Bẫy: cổ phiếu lại tăng 4%, nên cổ đông không phản đối."},{"q":"What will happen in July?","o":["The new office will open","Salaries will be reviewed","Shares will be offered to staff","A hiring event will be held"],"a":3,"ev":[9],"vi":"\"hold a recruitment event in the city in July\" = sự kiện tuyển dụng (paraphrase). Bẫy: văn phòng mở vào \"September\", không phải tháng 7."}],"ts":[0.4,8.72,15.31,22.79,30.62,37.86,41.14,47.27,52.81,57.41,62.84,68.64]},{"id":"p4-07","part":4,"level":1,"topic":"HR","title":"Interview invitation","title_vi":"Lời mời phỏng vấn từ nhà tuyển dụng","speakers":{"A":"F-US"},"lines":[["A","Hello, this is a message for Linh Nguyen. My name is Karen Wells, and I'm a recruiter at Talent Bridge."],["A","Thank you for applying for the senior backend developer position with our client, Orbit Payments."],["A","I'm happy to let you know that they were very impressed with your application."],["A","They'd like to invite you to a first-round interview by video call."],["A","The interview will last about forty-five minutes and will be with two members of their engineering team."],["A","They've suggested either Tuesday at two p.m. or Thursday at ten a.m., Vietnam time."],["A","Please let me know which time works better for you by end of day tomorrow."],["A","You'll also be asked to solve a short coding problem during the call, so make sure you have a laptop with a working camera."],["A","After the interview, I'll follow up with feedback within a few days."],["A","You can reply to my e-mail or call me back at 555-0147."],["A","Congratulations on getting this far, and I look forward to hearing from you."]],"questions":[{"q":"Why is the speaker calling?","o":["To offer the listener a job","To invite the listener to an interview","To ask for a reference","To cancel a video call"],"a":1,"ev":[3],"vi":"\"They'd like to invite you to a first-round interview\". Bẫy: chưa phải mời nhận việc (job offer), chỉ là vòng phỏng vấn đầu."},{"q":"How long will the interview last?","o":["About ten minutes","About two hours","About forty-five minutes","About an hour and a half"],"a":2,"ev":[4],"vi":"\"The interview will last about forty-five minutes\". Bẫy: \"two\" là số người phỏng vấn và giờ \"two p.m.\", \"ten\" là \"ten a.m.\"."},{"q":"What is the listener asked to do by tomorrow?","o":["Send a coding sample","Buy a new laptop","Call the client directly","Choose an interview time"],"a":3,"ev":[5,6],"vi":"\"let me know which time works better for you by end of day tomorrow\" → chọn giờ phỏng vấn. Bẫy: laptop chỉ cần có camera, không phải mua mới."},{"q":"What will the listener do during the interview?","o":["Give a presentation","Meet the company's CEO","Sign a contract","Solve a programming task"],"a":3,"ev":[7],"vi":"\"You'll also be asked to solve a short coding problem\" = giải bài lập trình (paraphrase). Bẫy: phỏng vấn với \"two members of their engineering team\", không phải CEO."}],"ts":[0.4,7.81,14.04,18.3,22.58,28.86,35.04,39.43,46.45,51.26,57.73]},{"id":"p4-08","part":4,"level":2,"topic":"Manufacturing","title":"Factory tour","title_vi":"Tham quan nhà máy","speakers":{"A":"M-GB"},"lines":[["A","Good morning, and welcome to Greenfield Electronics. I'm David, and I'll be your guide for today's tour of our main factory."],["A","This plant produces around five thousand circuit boards every day, which are shipped to customers in over thirty countries."],["A","The tour will take about an hour, and we'll start here in the assembly area."],["A","After that, we'll move on to the testing lab, and then we'll see the packaging department."],["A","Before we go in, please put on the safety glasses and the blue jackets you were given at reception."],["A","They help protect our products from dust and static electricity."],["A","Also, photography isn't permitted inside the testing lab, so please keep your phones in your pockets there."],["A","The machines are quite loud in the assembly area, so stay close to me if you want to hear my explanations."],["A","Trust me, you don't want to miss the robots."],["A","At the end of the tour, we'll head to the cafeteria for some refreshments, and I'll be happy to answer any questions."],["A","Alright, if everyone's ready, please follow me."]],"questions":[{"q":"Who most likely are the listeners?","o":["Factory workers","Visitors to a facility","Delivery drivers","Job applicants"],"a":1,"ev":[0],"vi":"\"welcome to Greenfield Electronics... I'll be your guide for today's tour\" → khách tham quan. Bẫy: \"Factory workers\" dùng lại từ factory nhưng họ không làm việc ở đó."},{"q":"Where will the tour begin?","o":["In the cafeteria","In the testing lab","In the assembly area","At reception"],"a":2,"ev":[2],"vi":"\"we'll start here in the assembly area\". Bẫy: cafeteria là nơi kết thúc; reception là nơi đã nhận áo và kính."},{"q":"What are listeners asked to do before entering?","o":["Leave their phones at reception","Put on protective gear","Sign a safety form","Watch a short video"],"a":1,"ev":[4],"vi":"\"put on the safety glasses and the blue jackets\" = mặc đồ bảo hộ (paraphrase). Bẫy: điện thoại chỉ cần để trong túi ở phòng testing lab."},{"q":"Why does the speaker say, \"Trust me, you don't want to miss the robots\"?","o":["To warn that the machines are dangerous","To explain why photos are not allowed","To point out an interesting part of the tour","To ask listeners to wait for the robots"],"a":2,"ev":[7,8],"vi":"Sau khi dặn \"stay close to me\", anh nhấn mạnh phần robot rất đáng xem. Bẫy: máy móc chỉ \"loud\" (ồn), không nói là nguy hiểm."}],"ts":[0.4,9.39,17.4,22.45,28.46,34.89,39.68,46.84,53.84,57.69,64.96]},{"id":"p4-09","part":4,"level":3,"topic":"IT","title":"New project-tracking tool","title_vi":"Hướng dẫn dùng công cụ quản lý dự án mới","speakers":{"A":"F-AU"},"lines":[["A","Today I'll walk you through TaskFlow, the project-tracking tool we're moving to next month."],["A","We've been using spreadsheets and e-mail threads, and things have been slipping through the cracks."],["A","First, open the link I sent this morning and sign in with your company account. You don't need to create a new password."],["A","On the left, you'll see your projects. Click on one, and you'll get a board with three columns: To Do, In Progress, and Done."],["A","To create a task, click the plus button, add a short title, and assign it to a team member."],["A","Make sure you always set a due date. Tasks without one won't show up in the weekly report."],["A","You can also attach files of up to twenty-five megabytes, but for anything bigger, please use a shared drive link."],["A","The old spreadsheets will be switched to read-only on the fifteenth, and they'll be archived completely at the end of the month."],["A","So any active tasks need to be moved into TaskFlow before the fifteenth."],["A","Now, I'll give you ten minutes to create two or three sample tasks of your own."],["A","If you get stuck, raise your hand and either Sam or I will come over."]],"questions":[{"q":"What is the main purpose of the workshop?","o":["To train staff on new software","To review weekly reports","To choose a new tracking tool","To explain a password policy"],"a":0,"ev":[0],"vi":"\"I'll walk you through TaskFlow, the project-tracking tool we're moving to\" → đào tạo dùng phần mềm mới. Bẫy: công cụ đã được chọn rồi, không phải đang chọn."},{"q":"According to the speaker, why should a due date be set?","o":["So the task can be assigned","So the task appears in a regular summary","So larger files can be attached","So the task moves to the Done column"],"a":1,"ev":[5],"vi":"\"Tasks without one won't show up in the weekly report\" → báo cáo hằng tuần = regular summary (paraphrase). Bẫy: \"assign it to a team member\" là bước khác."},{"q":"By when must active tasks be transferred?","o":["By the end of the month","Within ten minutes","By the fifteenth","By the end of next month"],"a":2,"ev":[7,8],"vi":"\"any active tasks need to be moved into TaskFlow before the fifteenth\". Bẫy: \"end of the month\" là lúc lưu trữ hẳn bảng tính cũ; \"ten minutes\" là thời gian thực hành."},{"q":"What will listeners most likely do next?","o":["Practice creating tasks","Archive old spreadsheets","Watch a demonstration by Sam","Reset their passwords"],"a":0,"ev":[9],"vi":"\"I'll give you ten minutes to create two or three sample tasks\" → thực hành tạo task. Bẫy: Sam chỉ hỗ trợ khi bị kẹt; không cần mật khẩu mới."}],"ts":[0.4,6.82,13.44,22.47,32.33,39.4,47.21,55.36,63.42,69.67,76.16]},{"id":"p4-10","part":4,"level":1,"topic":"Finance","title":"Quarterly results","title_vi":"Trình bày kết quả quý","speakers":{"A":"M-US"},"lines":[["A","Thanks, everyone. Let's move on to our results for the third quarter."],["A","Overall, it was a strong quarter. Total revenue reached four point two million dollars, up eight percent from the second quarter."],["A","Most of that growth came from our cloud services, which now make up nearly half of our sales."],["A","Our mobile app subscriptions also did well, especially in Japan and Australia."],["A","On the other hand, hardware sales dropped by about five percent."],["A","That wasn't a big surprise, since we stopped producing two older models in July."],["A","We also kept costs under control, mainly by reducing travel and moving more meetings online."],["A","As a result, our profit margin improved slightly."],["A","Looking ahead, we expect the fourth quarter to be even busier, with the holiday season and two major product launches."],["A","I'll send the full report to everyone by end of day, so please take a look before our planning session on Monday."],["A","Now, let's open it up for questions."]],"questions":[{"q":"What is the speaker mainly discussing?","o":["A company's financial performance","A new product launch","A change in travel policy","A hiring plan"],"a":0,"ev":[0,1],"vi":"\"our results for the third quarter... Total revenue\" → kết quả tài chính. Bẫy: \"product launches\" và \"reducing travel\" chỉ là chi tiết."},{"q":"By how much did total revenue increase?","o":["Two percent","Five percent","Eight percent","Fifty percent"],"a":2,"ev":[1],"vi":"\"up eight percent from the second quarter\". Bẫy: \"five percent\" là mức giảm của hardware; \"half\" là tỉ trọng cloud."},{"q":"Why does the speaker say, \"That wasn't a big surprise\"?","o":["Cloud sales always grow in summer","The hardware decline was expected","Travel was reduced as planned","The app was popular in Japan"],"a":1,"ev":[4,5],"vi":"Câu này nói về việc \"hardware sales dropped\" vì \"we stopped producing two older models\" → sụt giảm đã được dự đoán."},{"q":"What are listeners asked to do before Monday?","o":["Prepare a sales forecast","Reduce their travel","Plan a product launch","Read a document"],"a":3,"ev":[9],"vi":"\"please take a look before our planning session on Monday\" → đọc bản báo cáo (paraphrase \"Read a document\"). Bẫy: \"planning\" không có nghĩa là lên kế hoạch ra mắt sản phẩm."}],"ts":[0.4,6.53,15.86,22.4,28.61,33.81,39.94,46.89,51.34,59.42,66.85]},{"id":"p4-11","part":4,"level":2,"topic":"Office","title":"Coworking space ad","title_vi":"Quảng cáo không gian làm việc chung","speakers":{"A":"F-GB"},"lines":[["A","Tired of working from your kitchen table? Or paying too much for an office you only use three days a week?"],["A","Then come and check out HubWorks, the newest coworking space in the city center."],["A","Located just two minutes from Central Station, HubWorks offers fast Wi-Fi, quiet phone booths, and meeting rooms you can book online."],["A","Our members also enjoy free coffee, a rooftop terrace, and regular networking events with local start-ups."],["A","A flexible desk costs just one hundred and fifty dollars a month, and a private office for up to four people starts at six hundred."],["A","And this month only, new members get their first two weeks absolutely free."],["A","Not sure if it's right for you? Book a free tour on our website, and see the space for yourself."],["A","We're open from seven a.m. to ten p.m. on weekdays, and members with a private office have access twenty-four hours a day."],["A","Visit hubworks dot com today, and use the code START to get ten percent off your first month."],["A","HubWorks. Work your way."]],"questions":[{"q":"What is being advertised?","o":["A coffee shop","A shared workspace","A train station","A business course"],"a":1,"ev":[1],"vi":"\"the newest coworking space\" = không gian làm việc chung. Bẫy: \"free coffee\", \"Central Station\" chỉ là chi tiết."},{"q":"What is offered to new members this month?","o":["A free private office","Ten free coffee vouchers","Two weeks at no cost","A discount on meeting rooms"],"a":2,"ev":[5],"vi":"\"new members get their first two weeks absolutely free\". Bẫy: \"ten percent off\" là mã giảm giá tháng đầu, không phải phiếu cà phê."},{"q":"What are listeners encouraged to do if they are unsure?","o":["Call the main office","Visit Central Station","Arrange a visit online","Attend a networking event"],"a":2,"ev":[6],"vi":"\"Book a free tour on our website\" = đặt lịch tham quan trực tuyến (paraphrase). Bẫy: networking events là quyền lợi của thành viên."},{"q":"Who can use the space at any time of day?","o":["Private office members","All members","Start-up founders","Weekend visitors"],"a":0,"ev":[7],"vi":"\"members with a private office have access twenty-four hours a day\". Bẫy: thành viên thường chỉ vào được 7 a.m.–10 p.m. ngày thường."}],"ts":[0.4,8.67,14.88,25.47,33.86,43.55,49.78,57.71,66.9,74.37]},{"id":"p4-12","part":4,"level":3,"topic":"Office","title":"Fire drill this afternoon","title_vi":"Diễn tập phòng cháy chiều nay","speakers":{"A":"M-AU"},"lines":[["A","Hi, everyone, this is Mark from Facilities. Just a quick heads-up about this afternoon."],["A","We'll be holding a fire drill at around three fifteen, not at two as stated in last week's e-mail."],["A","When the alarm goes off, please stop what you're doing and leave the building by the nearest staircase."],["A","Do not use the elevators under any circumstances."],["A","Our meeting point is the parking lot behind the building, not the front entrance where we gathered last time."],["A","Floor wardens will be wearing orange vests, and they'll check that each area is empty."],["A","Once you reach the parking lot, please find your team leader so they can confirm you're there."],["A","The whole drill should take about twenty minutes, so you'll be back at your desks by around three thirty-five."],["A","I know some of you have client calls this afternoon."],["A","If you can't avoid one, let your manager know before lunch, and we'll see what we can do."],["A","Last year, it took us almost eight minutes to get everyone out. This time, we're aiming for under five."],["A","Thanks for your cooperation."]],"questions":[{"q":"Who most likely is the speaker?","o":["A team leader","A floor warden","A building facilities employee","A client manager"],"a":2,"ev":[0],"vi":"\"this is Mark from Facilities\" → nhân viên bộ phận cơ sở vật chất. Bẫy: \"floor wardens\" và \"team leader\" là những người khác được nhắc tới."},{"q":"Where should employees gather during the drill?","o":["At the front entrance","Near the elevators","By the nearest staircase","Behind the building"],"a":3,"ev":[4],"vi":"\"the parking lot behind the building\" → phía sau tòa nhà. Bẫy: \"front entrance\" là điểm tập trung lần trước; staircase là lối thoát."},{"q":"What should employees do after arriving at the meeting point?","o":["Put on orange vests","Check that each area is empty","Report to their team leader","Return to their desks"],"a":2,"ev":[6],"vi":"\"please find your team leader so they can confirm you're there\" = báo danh với trưởng nhóm. Bẫy: áo cam và kiểm tra khu vực là việc của floor wardens."},{"q":"Why does the speaker say, \"I know some of you have client calls this afternoon\"?","o":["To cancel the fire drill","To recognize a possible scheduling conflict","To ask staff to move all meetings","To remind managers about a deadline"],"a":1,"ev":[8,9],"vi":"Anh thừa nhận buổi diễn tập có thể trùng cuộc gọi khách hàng, rồi nói \"let your manager know before lunch, and we'll see what we can do\". Bẫy: không hủy diễn tập, cũng không bắt dời mọi cuộc họp."}],"ts":[0.4,7.11,13.34,19.07,22.82,28.89,34.23,39.38,45.51,48.98,54.61,62.07]},{"id":"p4-13","part":4,"level":1,"topic":"Logistics","title":"Wrong items delivered","title_vi":"Nhà cung cấp giao nhầm hàng","speakers":{"A":"F-US"},"lines":[["A","Hello, this is Jenny Lopez from Prime Office Supplies, calling for Mr. Tran at Bluewave Software."],["A","I'm calling about your order of office chairs that was delivered yesterday."],["A","Unfortunately, our warehouse made a mistake. You ordered twenty black chairs, but we sent you twenty gray ones."],["A","I'm very sorry about that."],["A","We'll deliver the correct chairs this Thursday morning, between nine and eleven."],["A","Our driver will pick up the gray chairs at the same time, so please keep them in their original boxes if possible."],["A","Of course, there's no extra charge for this."],["A","And to apologize, we'll take fifteen percent off your next order."],["A","Could you call me back to confirm that someone will be at the office on Thursday to receive the delivery?"],["A","My direct number is 555-0182."],["A","Again, sorry for the trouble, and thank you for your patience."]],"questions":[{"q":"What is the purpose of the message?","o":["To advertise new office chairs","To report a problem with an order","To request payment for a delivery","To cancel an order"],"a":1,"ev":[1,2],"vi":"\"our warehouse made a mistake\" về đơn ghế → báo lỗi đơn hàng. Bẫy: \"no extra charge\" nên không phải đòi tiền."},{"q":"What was wrong with the delivery?","o":["The chairs were damaged","Too few chairs were sent","The chairs were the wrong color","The delivery was late"],"a":2,"ev":[2],"vi":"\"You ordered twenty black chairs, but we sent you twenty gray ones\" → sai màu. Bẫy: số lượng vẫn là 20, đủ."},{"q":"What does the speaker offer?","o":["Free delivery for a year","Twenty extra chairs","A full refund","A discount on a future order"],"a":3,"ev":[7],"vi":"\"we'll take fifteen percent off your next order\" = giảm giá đơn sau (paraphrase). Bẫy: \"twenty\" là số ghế đã đặt."},{"q":"What is the listener asked to do?","o":["Return the chairs to the warehouse","Choose a different color","Pay a delivery fee","Confirm that someone can receive a delivery"],"a":3,"ev":[8],"vi":"\"call me back to confirm that someone will be at the office on Thursday\". Bẫy: tài xế sẽ tự đến lấy ghế xám, người nghe không phải mang trả."}],"ts":[0.4,7.49,12.0,19.98,22.3,26.99,34.16,37.17,41.53,47.3,51.59]},{"id":"p4-14","part":4,"level":2,"topic":"IT","title":"New app release briefing","title_vi":"Giới thiệu tính năng bản app mới","speakers":{"A":"M-US"},"lines":[["A","Hi, team. I want to give you a quick overview of version 3.0 of our mobile banking app, which goes live next Tuesday."],["A","The biggest change is the new home screen. Users can now see all their accounts and recent transactions in one place."],["A","We've also added fingerprint and face login, which our customers have been asking for since last year."],["A","Another new feature is instant transfers between our bank and five partner banks."],["A","Those transfers used to take up to two business days, so this is a big deal."],["A","On top of that, the app now supports dark mode and loads about thirty percent faster."],["A","Since you're the ones who'll be answering customers' questions, it's important that you understand these changes."],["A","We'll run a short training session on Monday afternoon, and I'll share a one-page summary right after this meeting."],["A","If customers report any bugs, please log them in the support system with screenshots, and tag them 'version three'."],["A","The development team will be monitoring those reports closely during the first week."],["A","Okay, let's take a look at a quick demo."]],"questions":[{"q":"Who most likely are the listeners?","o":["App developers","Customer support staff","Bank investors","New customers"],"a":1,"ev":[6,8],"vi":"\"you're the ones who'll be answering customers' questions\" và \"log them in the support system\" → nhân viên hỗ trợ khách hàng. Bẫy: \"development team\" được nhắc như một nhóm khác."},{"q":"Why does the speaker say, \"this is a big deal\"?","o":["To stress that a feature is a major improvement","To warn about a security risk","To announce a new partnership deal","To complain about a delay"],"a":0,"ev":[3,4],"vi":"Chuyển khoản trước đây \"used to take up to two business days\", nay là tức thì → cải tiến lớn. Bẫy: \"deal\" ở đây không phải hợp đồng với \"partner banks\"."},{"q":"When will the training session be held?","o":["Next Tuesday","On Monday afternoon","Right after this meeting","During the first week"],"a":1,"ev":[7],"vi":"\"a short training session on Monday afternoon\". Bẫy: thứ Ba là ngày ra mắt app; \"right after this meeting\" là lúc gửi bản tóm tắt."},{"q":"What will most likely happen next?","o":["A demonstration will be shown","Bugs will be logged","The app will go live","Customers will be called"],"a":0,"ev":[10],"vi":"\"let's take a look at a quick demo\" → sẽ xem bản demo. Bẫy: app ra mắt \"next Tuesday\", không phải ngay sau đó."}],"ts":[0.4,10.25,19.12,25.88,31.73,37.38,43.9,50.66,57.99,66.09,71.53]},{"id":"p4-15","part":4,"level":3,"topic":"Service","title":"AI in customer service","title_vi":"AI trong chăm sóc khách hàng","speakers":{"A":"F-GB"},"lines":[["A","Thank you. It's great to be here."],["A","When we first introduced an AI chat assistant at our company three years ago, I'll admit I was skeptical."],["A","Our customer service team was handling about eight thousand inquiries a week, and I worried that a chatbot would just frustrate people."],["A","Well, I was wrong. Today, the assistant resolves around sixty percent of inquiries on its own, without any human involvement."],["A","Average waiting time has dropped from twelve minutes to under two."],["A","But here's what surprised me most: our customer satisfaction scores actually went up."],["A","That's because our human agents now spend their time on the complicated cases, where empathy really matters."],["A","We didn't cut a single job. Instead, we retrained our staff to handle escalations and to review the AI's answers."],["A","Of course, it wasn't all smooth. In the first few months, the assistant gave some incorrect answers about refunds."],["A","So my advice is simple: start small, keep humans in the loop, and measure everything."],["A","In a moment, I'll show you some real conversations, and you can judge the results for yourselves."]],"questions":[{"q":"What is the talk mainly about?","o":["Building a chatbot from scratch","Reducing the number of support staff","A new refund policy","One company's experience with AI support"],"a":3,"ev":[1,3],"vi":"Cả bài kể kết quả khi công ty \"introduced an AI chat assistant\" → trải nghiệm dùng AI hỗ trợ khách hàng. Bẫy: \"We didn't cut a single job\" nên không phải cắt giảm nhân sự."},{"q":"Why does the speaker say, \"Well, I was wrong\"?","o":["The assistant turned out to be effective","She gave customers incorrect information","She miscounted the weekly inquiries","She chose the wrong software vendor"],"a":0,"ev":[1,2,3],"vi":"Cô từng \"skeptical\" và lo chatbot làm khách bực, nhưng thực tế AI tự giải quyết 60% yêu cầu → hóa ra hiệu quả. Bẫy: \"incorrect answers\" là lỗi của AI, không phải của cô."},{"q":"What does the speaker say about the company's support staff?","o":["Some of them were let go","They answer sixty percent of inquiries","They now review refund requests only","They focus on more difficult cases"],"a":3,"ev":[6,7],"vi":"\"human agents now spend their time on the complicated cases\" = tập trung vào ca khó (paraphrase). Bẫy: 60% là phần AI tự xử lý, không phải nhân viên."},{"q":"What will the speaker most likely do next?","o":["Present examples of chats","Answer questions from the audience","Introduce another speaker","Explain the refund rules"],"a":0,"ev":[10],"vi":"\"I'll show you some real conversations\" → trình bày ví dụ hội thoại thực tế. Bẫy: không nhắc tới phần hỏi đáp hay diễn giả khác."}],"ts":[0.4,4.66,12.84,22.38,32.64,37.91,44.91,52.75,62.6,72.24,79.48]},{"id":"p4-16","part":4,"level":1,"topic":"HR","title":"New parental leave and wellness benefits","title_vi":"Chế độ nghỉ thai sản và phúc lợi sức khỏe mới","speakers":{"A":"F-US"},"lines":[["A","Good morning, everyone. This is Karen Liu from Human Resources with a quick update on our employee benefits."],["A","Starting January first, we're expanding our parental leave program."],["A","All new parents, regardless of gender, will now receive sixteen weeks of fully paid leave, up from ten weeks."],["A","We're also launching a new wellness benefit."],["A","Every full-time employee will get a monthly allowance of fifty dollars to spend on gym memberships, fitness classes, or mental health apps."],["A","Part-time staff will receive half that amount, so twenty-five dollars a month."],["A","To use the allowance, simply keep your receipts and submit them through the HR portal by the last Friday of each month."],["A","We know you'll have questions, so we're holding two information sessions next week."],["A","The first one is on Tuesday at noon in the main cafeteria, and the second is on Thursday at four in Conference Room B."],["A","Lunch will be provided at the Tuesday session."],["A","Before then, please take a few minutes to read the benefits guide that we emailed this morning."],["A","If anything is unclear, feel free to reach out to me directly. Thanks, and have a great day."]],"questions":[{"q":"What is the announcement mainly about?","o":["Changes to employee benefits","A new HR manager","A cafeteria renovation","New working hours"],"a":0,"ev":[0,1],"vi":"Người nói giới thiệu \"a quick update on our employee benefits\" (nghỉ thai sản + phúc lợi sức khỏe). \"cafeteria\" chỉ là nơi họp, là bẫy."},{"q":"How much will part-time staff receive each month?","o":["Ten dollars","Sixteen dollars","Twenty-five dollars","Fifty dollars"],"a":2,"ev":[4,5],"vi":"\"Part-time staff will receive half that amount, so twenty-five dollars a month.\" Bẫy: 50 đô là mức của nhân viên toàn thời gian."},{"q":"Where will the Thursday session take place?","o":["In the main cafeteria","In Conference Room B","In the HR office","Online"],"a":1,"ev":[8],"vi":"\"the second is on Thursday at four in Conference Room B\". Bẫy: \"main cafeteria\" là buổi thứ Ba."},{"q":"What are listeners asked to do before the sessions?","o":["Submit their receipts","Sign up for a gym","Contact their managers","Read a document sent by email"],"a":3,"ev":[10],"vi":"\"please take a few minutes to read the benefits guide that we emailed\" = đọc tài liệu gửi qua email. \"receipts\" là bước dùng phụ cấp hàng tháng, không phải việc cần làm trước buổi họp."}],"ts":[0.4,7.71,12.62,20.75,23.9,33.47,38.62,46.91,52.06,59.71,62.99,69.19]},{"id":"p4-17","part":4,"level":2,"topic":"IT","title":"Sprint retrospective summary","title_vi":"Tổng kết buổi retrospective của sprint","speakers":{"A":"M-GB"},"lines":[["A","Right, thanks everyone for joining. I'll keep this short and summarise what came out of yesterday's sprint retrospective."],["A","First, the good news: we delivered eleven of the twelve stories we committed to, which is our best result this quarter."],["A","The one we didn't finish, the payment export feature, has been carried over to the next sprint."],["A","On the downside, a lot of you mentioned that code reviews were taking too long."],["A","Some pull requests sat for three days before anyone looked at them."],["A","So going forward, we're trying a new rule: every pull request should get a first review within one working day."],["A","Tomas has kindly agreed to set up a Slack reminder that pings reviewers automatically."],["A","Another point was that our stand-ups were regularly running over fifteen minutes."],["A","Well, I've timed myself, and I'm not innocent either."],["A","From Monday, we'll move any detailed discussion to a separate thread after the stand-up."],["A","Finally, please add your estimates for the new backlog items by end of day Thursday, so we can plan properly on Friday morning."],["A","Any questions, just give me a shout."]],"questions":[{"q":"Who most likely is the speaker?","o":["A customer support agent","A software team facilitator","A finance manager","A job candidate"],"a":1,"ev":[0,1],"vi":"Người nói tóm tắt \"sprint retrospective\", nói về stories, pull requests, stand-up → người điều phối nhóm phần mềm (scrum master). Bẫy: \"payment export\" không liên quan tài chính."},{"q":"What has Tomas agreed to do?","o":["Finish the payment export feature","Lead the stand-up meetings","Set up automatic reminders","Review all pull requests"],"a":2,"ev":[6],"vi":"\"Tomas has kindly agreed to set up a Slack reminder that pings reviewers automatically\" = thiết lập nhắc nhở tự động. Bẫy: \"Review all pull requests\" dùng lại từ trong bài."},{"q":"Why does the speaker say, \"I'm not innocent either\"?","o":["To admit he also made meetings run long","To deny a complaint about reviews","To explain why a story was unfinished","To apologize for missing a deadline"],"a":0,"ev":[7,8],"vi":"Sau khi nói stand-up hay quá 15 phút, \"I've timed myself, and I'm not innocent either\" = thừa nhận chính anh cũng làm họp kéo dài."},{"q":"What are listeners asked to do by Thursday?","o":["Attend a planning meeting","Submit their pull requests","Join a Slack channel","Provide estimates for new tasks"],"a":3,"ev":[10],"vi":"\"please add your estimates for the new backlog items by end of day Thursday\" = gửi ước lượng cho việc mới. Bẫy: họp lập kế hoạch là sáng thứ Sáu."}],"ts":[0.4,9.1,16.77,23.05,28.56,33.4,40.66,46.53,51.99,56.37,62.29,70.92]},{"id":"p4-18","part":4,"level":3,"topic":"Travel","title":"Morning traffic and weather","title_vi":"Giao thông và thời tiết buổi sáng","speakers":{"A":"F-AU"},"lines":[["A","Good morning, it's seven fifteen, and here's your traffic and weather update on City Radio."],["A","If you're heading into the city on the Northern Highway, expect delays of around twenty-five minutes."],["A","A truck has broken down near Exit 12, and two of the three southbound lanes are closed."],["A","Crews are on the scene, but they don't expect to clear it before eight thirty."],["A","So if you can, take Riverside Drive instead; it's moving freely at the moment."],["A","Commuters on the Bay Line trains, good news: services are back to normal after yesterday's signal fault."],["A","Now, the weather. It's a cool fourteen degrees right now, climbing to around twenty-two by the afternoon."],["A","But don't let the sunshine fool you."],["A","A band of heavy rain is moving in from the west and should hit the city around five o'clock, just in time for the evening rush."],["A","The weather bureau has also issued a wind warning for coastal areas from six tonight."],["A","We'll have another update at seven forty-five, right after the news."]],"questions":[{"q":"Who most likely is the speaker?","o":["A truck driver","A train operator","A radio host","A weather bureau official"],"a":2,"ev":[0],"vi":"\"here's your traffic and weather update on City Radio\" → người dẫn chương trình radio. Bẫy: \"truck\", \"Bay Line trains\", \"weather bureau\" đều xuất hiện trong bài nhưng không phải người nói."},{"q":"What are drivers advised to do?","o":["Use an alternative road","Leave home before eight thirty","Take the Bay Line trains","Avoid coastal areas"],"a":0,"ev":[4],"vi":"\"take Riverside Drive instead\" = đi đường khác (paraphrase). Bẫy: \"eight thirty\" là giờ dự kiến dọn xong xe hỏng; tàu Bay Line chỉ được thông báo đã chạy lại, không được khuyên."},{"q":"Why does the speaker say, \"don't let the sunshine fool you\"?","o":["To suggest the temperature will drop sharply","To warn that the weather will change later","To recommend wearing sunscreen","To correct an earlier forecast"],"a":1,"ev":[7,8],"vi":"Ngay sau đó là \"A band of heavy rain ... should hit the city around five o'clock\" → cảnh báo thời tiết sẽ xấu đi sau đó. Bẫy: nhiệt độ thực ra tăng lên 22 độ."},{"q":"When will the rain most likely reach the city?","o":["At 7:45 a.m.","At 8:30 a.m.","At 6 p.m.","Around 5 p.m."],"a":3,"ev":[8],"vi":"\"should hit the city around five o'clock\". Bẫy số: 7:45 là bản tin kế tiếp, 8:30 là giờ dọn đường, 6 giờ tối là cảnh báo gió."}],"ts":[0.4,7.37,14.47,21.42,26.95,33.21,41.14,49.84,53.26,61.92,68.58]},{"id":"p4-19","part":4,"level":1,"topic":"HR","title":"Employee of the Year award","title_vi":"Trao giải Nhân viên của năm","speakers":{"A":"M-US"},"lines":[["A","Good evening, everyone, and thank you all for coming to our annual company dinner."],["A","Now it's my great pleasure to present this year's Employee of the Year award."],["A","This year's winner is Priya Sharma from our customer success team."],["A","Priya joined us just three years ago, and she has already made a huge difference."],["A","Last spring, she created a new onboarding program for our clients."],["A","Thanks to her work, customer complaints dropped by forty percent."],["A","She also trained over twenty new team members this year, always with patience and a smile."],["A","Her colleagues describe her as the person everyone goes to when there's a problem."],["A","As a thank-you, Priya will receive a bonus and an extra five days of paid vacation."],["A","She'll also get a reserved parking spot for the next twelve months."],["A","Priya, please come up to the stage to accept your award."],["A","Everyone, let's give her a big round of applause."]],"questions":[{"q":"Where is the speech being given?","o":["At a training session","At a company dinner","At a client meeting","At a job interview"],"a":1,"ev":[0],"vi":"\"thank you all for coming to our annual company dinner\" → tiệc tối của công ty. Bẫy: \"trained\" và \"clients\" có trong bài nhưng không phải địa điểm."},{"q":"What did Priya create?","o":["A program for new clients","A complaint form","A parking system","A training video"],"a":0,"ev":[4],"vi":"\"she created a new onboarding program for our clients\" = chương trình cho khách hàng mới. Bẫy: \"complaints\", \"parking\" xuất hiện ở ý khác."},{"q":"By how much did customer complaints decrease?","o":["Three percent","Twelve percent","Twenty percent","Forty percent"],"a":3,"ev":[5],"vi":"\"customer complaints dropped by forty percent\". Bẫy số: 3 năm làm việc, 20 người được đào tạo, 12 tháng chỗ đỗ xe."},{"q":"What will Priya most likely do next?","o":["Lead a training session","Take a vacation","Go up to the stage","Introduce a new employee"],"a":2,"ev":[10],"vi":"\"Priya, please come up to the stage to accept your award\" → cô ấy sẽ lên sân khấu. Bẫy: \"vacation\" là phần thưởng, không phải việc làm ngay."}],"ts":[0.4,5.93,11.01,15.97,21.58,26.7,31.88,37.84,43.11,49.13,53.8,58.32]},{"id":"p4-20","part":4,"level":2,"topic":"Office","title":"Parking garage repairs","title_vi":"Sửa chữa bãi đỗ xe","speakers":{"A":"F-GB"},"lines":[["A","Hello, this message is for Mr. Daniel Ortiz in suite 410. This is Fiona Clarke, the building manager at Harbour Tower."],["A","I'm calling to give you a heads-up about some repairs in the underground car park."],["A","Starting next Monday, the fifth, contractors will be repairing cracks in the concrete on levels B1 and B2."],["A","The work should take about two weeks, weather permitting."],["A","During that time, those two levels will be completely closed."],["A","I know that's not ideal, especially since your team uses six of the spaces on B2."],["A","We've arranged temporary parking at the City Centre garage on Elm Street, about a five-minute walk away."],["A","There's no charge for tenants; you'll just need to show a visitor pass at the entrance."],["A","I can have passes ready for your team, but I need the names and licence plate numbers of everyone who'll be parking there."],["A","Could you email that list to me by Wednesday?"],["A","If you have any questions, you can reach me on extension 225. Thanks very much."]],"questions":[{"q":"What is the purpose of the message?","o":["To announce a rent increase","To notify a tenant about repairs","To request payment for parking","To report damage to a car"],"a":1,"ev":[1],"vi":"\"I'm calling to give you a heads-up about some repairs in the underground car park\" = báo trước cho người thuê về việc sửa chữa."},{"q":"Why does the speaker say, \"I know that's not ideal\"?","o":["To apologize for a billing error","To explain why the work was delayed","To suggest the listener move offices","To acknowledge an inconvenience for the listener's team"],"a":3,"ev":[4,5],"vi":"Hai tầng bị đóng hoàn toàn và \"your team uses six of the spaces on B2\" → cô thừa nhận việc này gây bất tiện cho nhóm của người nghe."},{"q":"How much will the temporary parking cost tenants?","o":["Nothing","Six pounds a day","Two hundred and twenty-five pounds","Half the usual rate"],"a":0,"ev":[7],"vi":"\"There's no charge for tenants\" = miễn phí. Bẫy số: 6 là số chỗ đỗ, 225 là số máy lẻ."},{"q":"What does the speaker ask the listener to do?","o":["Pick up passes on Monday","Send information about drivers","Call back before Wednesday","Move cars to level B1"],"a":1,"ev":[8,9],"vi":"\"I need the names and licence plate numbers ... Could you email that list to me by Wednesday?\" = gửi thông tin người lái. Bẫy: \"Wednesday\" là hạn gửi email, không phải gọi lại; B1 cũng bị đóng."}],"ts":[0.4,10.81,16.68,25.28,29.62,34.74,41.43,49.39,55.66,63.74,67.6]},{"id":"p4-21","part":4,"level":3,"topic":"Events","title":"Webinar opening","title_vi":"Mở đầu hội thảo trực tuyến","speakers":{"A":"M-AU"},"lines":[["A","Hi everyone, and welcome to today's webinar, Scaling Cloud Infrastructure on a Budget. I'm Liam Walker, and I'll be your host."],["A","We've got just over three hundred people joining from twelve countries, so thanks for being here, wherever you are."],["A","Before we dive in, a few housekeeping notes."],["A","Everyone's microphone has been muted to keep the background noise down."],["A","If you've got a question, please type it into the Q&A box rather than the chat, because the chat moves pretty fast and things get lost."],["A","Here's the plan for the next ninety minutes."],["A","Our first speaker, Dr. Nina Patel, will talk for about forty minutes on cost monitoring tools."],["A","After that, we'll take a ten-minute break, and then our second speaker will walk you through a real migration case study."],["A","We'll save the last twenty minutes for your questions."],["A","Oh, and I've been asked this already, so I'll say it now: yes, you'll get the slides."],["A","A recording and the slide deck will be emailed to all registered attendees within forty-eight hours."],["A","Okay, without further ado, let's bring in Nina."]],"questions":[{"q":"What is the webinar mainly about?","o":["Hiring cloud engineers","Managing international teams","Migrating email systems","Cutting the cost of cloud systems"],"a":3,"ev":[0],"vi":"Tên webinar \"Scaling Cloud Infrastructure on a Budget\" → mở rộng hạ tầng cloud với chi phí thấp (paraphrase). Bẫy: \"twelve countries\", \"migration\" chỉ là chi tiết phụ."},{"q":"How long will Dr. Patel speak?","o":["Ten minutes","Forty minutes","Twenty minutes","Ninety minutes"],"a":1,"ev":[6],"vi":"\"Dr. Nina Patel, will talk for about forty minutes\". Bẫy số: 90 là cả buổi, 10 là giải lao, 20 là phần hỏi đáp."},{"q":"Why does the speaker say, \"I've been asked this already\"?","o":["To address a common concern in advance","To complain about too many questions","To ask attendees to stop using the chat","To introduce the second speaker"],"a":0,"ev":[9],"vi":"Anh nói vậy rồi trả lời luôn \"yes, you'll get the slides\" → giải đáp trước một thắc mắc nhiều người có. Không có ý phàn nàn."},{"q":"What will most likely happen next?","o":["A case study will be presented","The slides will be emailed","A speaker will begin her talk","Attendees will take a short break"],"a":2,"ev":[11],"vi":"\"let's bring in Nina\" → Dr. Nina Patel (nữ) sẽ bắt đầu nói. Bẫy: case study và giải lao diễn ra sau; slides gửi trong 48 giờ."}],"ts":[0.4,9.46,16.05,19.62,24.0,31.74,34.71,41.06,48.06,51.43,57.52,63.36]},{"id":"p4-22","part":4,"level":1,"topic":"Sales","title":"Weekend electronics sale","title_vi":"Khuyến mãi đồ điện tử cuối tuần","speakers":{"A":"F-US"},"lines":[["A","Attention, shoppers! Welcome to TechMart."],["A","This weekend only, we're having a huge sale on office electronics."],["A","All printers and scanners are thirty percent off."],["A","Wireless keyboards and mice are buy one, get one free."],["A","And if you're setting up a home office, don't miss our laptop deals in aisle seven."],["A","Selected laptops are two hundred dollars off the regular price."],["A","Members of our TechMart Rewards program get an extra ten percent off at the register."],["A","Not a member yet? Signing up is free and only takes a minute at the customer service desk near the main entrance."],["A","The sale ends Sunday at six p.m., so don't wait."],["A","Also, today only, our technicians are offering free laptop setup with any laptop purchase."],["A","Thank you for shopping at TechMart, and have a great day."]],"questions":[{"q":"Where is the announcement being made?","o":["In an electronics store","At a trade show","In an office","At a repair shop"],"a":0,"ev":[0,1],"vi":"\"Attention, shoppers! Welcome to TechMart\" + khuyến mãi đồ điện tử → trong cửa hàng điện tử. Bẫy: \"office\" là loại sản phẩm (office electronics)."},{"q":"What discount is offered on printers?","o":["Ten percent","Thirty percent","Two hundred dollars","Buy one, get one free"],"a":1,"ev":[2],"vi":"\"All printers and scanners are thirty percent off\". Bẫy: 10% dành cho thành viên, 200 đô cho laptop, mua 1 tặng 1 cho bàn phím/chuột."},{"q":"What are shoppers who are not members encouraged to do?","o":["Visit aisle seven","Call a technician","Register at the customer service desk","Ask for a discount at the register"],"a":2,"ev":[7],"vi":"\"Not a member yet? Signing up is free ... at the customer service desk\" = đăng ký tại quầy dịch vụ khách hàng. Bẫy: \"register\" (quầy thu ngân) là nơi thành viên được giảm thêm."},{"q":"What is available today only?","o":["Free membership","Discounted printers","An extra ten percent off","Free laptop setup"],"a":3,"ev":[9],"vi":"\"today only, our technicians are offering free laptop setup\". Bẫy: các ưu đãi khác kéo dài cả cuối tuần; đăng ký thành viên luôn miễn phí."}],"ts":[0.4,4.25,8.73,12.35,16.08,21.3,25.73,31.36,39.08,42.67,49.16]},{"id":"p4-23","part":4,"level":2,"topic":"Business","title":"Merger announcement","title_vi":"Thông báo sáp nhập","speakers":{"A":"M-GB"},"lines":[["A","Good afternoon, everyone, and thank you for joining this town hall, both here in London and online."],["A","I'll get straight to the point. This morning, our board approved a merger with Brightline Analytics."],["A","Many of you know Brightline; they're based in Manchester and they're one of the strongest data analytics firms in the country."],["A","Together, we'll have around two thousand employees and offices in five countries."],["A","I want to be clear about one thing: this is about growth, not cost-cutting."],["A","We are not planning any layoffs as part of this deal."],["A","The merger is expected to close by the end of March, pending regulatory approval."],["A","Until then, it's business as usual. Please keep serving your clients exactly as you do today."],["A","I also know news travels fast, so please don't discuss the deal with clients or the press until our public announcement on Thursday."],["A","Your managers will hold team meetings tomorrow to answer your questions in more detail."],["A","And of course, my door is always open."]],"questions":[{"q":"What is the main topic of the talk?","o":["A new client contract","The combining of two companies","An office move to Manchester","A change in senior management"],"a":1,"ev":[1],"vi":"\"our board approved a merger with Brightline Analytics\" → hai công ty hợp nhất (paraphrase \"merger\"). Bẫy: Manchester là trụ sở của Brightline, không phải nơi chuyển đến."},{"q":"What does the speaker emphasize about the merger?","o":["It will mainly reduce costs","It requires staff to relocate","It will not result in job losses","It has already received regulatory approval"],"a":2,"ev":[4,5],"vi":"\"We are not planning any layoffs\" = không cắt giảm nhân sự. Bẫy: \"not cost-cutting\" (ngược với đáp án 1); việc phê duyệt của cơ quan quản lý vẫn đang chờ (\"pending\")."},{"q":"When is the merger expected to be completed?","o":["Tomorrow","On Thursday","Within five weeks","By the end of March"],"a":3,"ev":[6],"vi":"\"expected to close by the end of March\". Bẫy: \"tomorrow\" là họp nhóm, \"Thursday\" là công bố chính thức."},{"q":"What are listeners asked to do?","o":["Keep the news confidential for now","Contact Brightline employees","Inform clients about the deal","Attend a press event on Thursday"],"a":0,"ev":[8],"vi":"\"please don't discuss the deal with clients or the press until our public announcement\" = giữ bí mật tạm thời. Bẫy: \"Inform clients\" ngược nghĩa."}],"ts":[0.4,7.21,14.9,22.33,28.25,33.83,38.09,44.23,51.61,59.93,65.72]},{"id":"p4-24","part":4,"level":3,"topic":"IT","title":"Password and two-factor policy","title_vi":"Chính sách mật khẩu và xác thực hai lớp","speakers":{"A":"F-AU"},"lines":[["A","Hi all, it's Megan from the IT security team, with a reminder about the policy changes we announced last month."],["A","From the fifteenth, all passwords must be at least fourteen characters long, up from eight."],["A","You'll also be required to change them every ninety days rather than every sixty."],["A","So, longer passwords, but fewer changes; it's not all bad news."],["A","The bigger change is two-factor authentication."],["A","Every account that can access customer data must have it switched on by the end of this month."],["A","After that, accounts without it will be locked automatically, and you'll need to raise a ticket to get back in."],["A","We recommend using the Authenticator app rather than text messages, since it's more secure and works without phone signal."],["A","Setup takes about five minutes, and there's a step-by-step guide on the intranet."],["A","If you'd rather have someone walk you through it, we're running drop-in sessions on Wednesday and Friday afternoons in room 3C."],["A","And please don't share your codes with anyone, including people claiming to be from IT. We'll never ask for them."]],"questions":[{"q":"What is the purpose of the talk?","o":["To report a recent data breach","To introduce new IT staff","To promote a new mobile app","To remind staff of upcoming security rules"],"a":3,"ev":[0],"vi":"\"a reminder about the policy changes we announced last month\" → nhắc lại quy định bảo mật sắp áp dụng. Bẫy: \"Authenticator app\" chỉ là khuyến nghị phụ."},{"q":"Why does the speaker say, \"it's not all bad news\"?","o":["To point out that one requirement is becoming less strict","To announce that the policy has been cancelled","To say passwords can now be shorter","To praise staff for following the rules"],"a":0,"ev":[1,2,3],"vi":"Mật khẩu dài hơn nhưng chỉ phải đổi \"every ninety days rather than every sixty\" → một yêu cầu được nới lỏng. Bẫy: mật khẩu dài hơn (14 ký tự), không ngắn hơn."},{"q":"What will happen to accounts without two-factor authentication after the deadline?","o":["They will be deleted","They will be blocked","They will receive a text message","They will need a new password"],"a":1,"ev":[5,6],"vi":"\"accounts without it will be locked automatically\" = bị khóa (paraphrase \"blocked\"). Bẫy: không bị xóa; \"text messages\" là phương án xác thực."},{"q":"What can listeners do if they want personal assistance?","o":["Raise a support ticket","Download a guide from the intranet","Visit room 3C on certain afternoons","Reply to last month's email"],"a":2,"ev":[9],"vi":"\"If you'd rather have someone walk you through it ... drop-in sessions on Wednesday and Friday afternoons in room 3C\". Bẫy: hướng dẫn trên intranet là tự làm, không có người hỗ trợ; ticket dùng khi tài khoản bị khóa."}],"ts":[0.4,8.81,15.6,21.75,27.79,31.96,38.43,45.74,54.61,60.57,69.66]},{"id":"p4-25","part":4,"level":1,"topic":"Sales","title":"Covering a client call","title_vi":"Nhờ đồng nghiệp nhận cuộc gọi khách hàng","speakers":{"A":"M-US"},"lines":[["A","Hi Jenny, it's Mark. I hope your morning's going well."],["A","I'm calling because I need a favor."],["A","I've got a client call with Green Valley Foods tomorrow at ten a.m., but my flight to Chicago was moved earlier, and I'll be in the air at that time."],["A","Would you be able to take the call for me?"],["A","It shouldn't take more than thirty minutes."],["A","They mainly want an update on the delivery schedule for their new order."],["A","I've put all the details in a shared folder called Green Valley, including the latest shipping dates."],["A","Their contact is Mr. Brown, their purchasing manager. He's very friendly."],["A","If he asks about pricing, just tell him I'll follow up by email on Friday."],["A","Please let me know by end of day if you can do it, so I can give him a heads-up about the change."],["A","You can text me or call my cell. Thanks so much, I owe you one."]],"questions":[{"q":"Why is the speaker calling?","o":["To book a flight to Chicago","To cancel an order","To ask a colleague to take his place on a call","To complain about a delivery"],"a":2,"ev":[1,2,3],"vi":"\"I need a favor ... Would you be able to take the call for me?\" → nhờ đồng nghiệp nhận cuộc gọi thay. Bẫy: chuyến bay đã được đặt, chỉ bị đổi giờ."},{"q":"When is the client call?","o":["Today at ten","On Friday","At the end of the day","Tomorrow morning"],"a":3,"ev":[2],"vi":"\"a client call with Green Valley Foods tomorrow at ten a.m.\" = sáng mai. Bẫy: Friday là ngày gửi email giá, \"end of day\" là hạn trả lời."},{"q":"What does the client mainly want to discuss?","o":["A delivery schedule","New prices","A flight change","A contract renewal"],"a":0,"ev":[5],"vi":"\"They mainly want an update on the delivery schedule\". Bẫy: \"pricing\" chỉ được nhắc nếu khách hỏi."},{"q":"What does the speaker ask Jenny to do by end of day?","o":["Email the client about pricing","Tell him if she is available","Update the shared folder","Call Mr. Brown"],"a":1,"ev":[9],"vi":"\"Please let me know by end of day if you can do it\" = báo cho anh biết cô có nhận được không. Bẫy: email về giá là việc của Mark vào thứ Sáu."}],"ts":[0.4,4.21,6.6,15.23,17.52,20.27,24.27,30.64,35.72,40.34,45.49]},{"id":"p4-26","part":4,"level":2,"topic":"Events","title":"Conference schedule changes","title_vi":"Thay đổi lịch hội nghị","speakers":{"A":"F-GB"},"lines":[["A","Good morning, and welcome to day two of the Asia-Pacific Software Summit."],["A","Before we begin, I have a few changes to today's schedule to share."],["A","First, the keynote by Dr. Hassan, originally scheduled for nine thirty, will now start at ten, as his flight landed later than expected."],["A","To fill the gap, we've moved the sponsor showcase forward, so you can visit the exhibition hall right after this announcement."],["A","Second, the workshop on API design has been moved from Room 2 to the Grand Ballroom."],["A","We've had far more sign-ups than we planned for, which is great news, but Room 2 only seats fifty."],["A","Third, the panel discussion on AI in testing has unfortunately been cancelled."],["A","If you registered for it, you're welcome to join any other afternoon session instead."],["A","Lunch will be served at twelve thirty on the terrace, as planned."],["A","The updated schedule is in the conference app, so please refresh it to see the latest version."],["A","Thank you, and enjoy the day."]],"questions":[{"q":"Who most likely is the speaker?","o":["An event organizer","A keynote speaker","A sponsor representative","A workshop instructor"],"a":0,"ev":[0,1],"vi":"Người nói chào mừng ngày thứ hai của hội nghị và \"have a few changes to today's schedule to share\" → ban tổ chức sự kiện."},{"q":"Why has the keynote been delayed?","o":["The room is being prepared","Too many people signed up","There is a technical problem","The speaker's travel was delayed"],"a":3,"ev":[2],"vi":"\"his flight landed later than expected\" = chuyến đi của diễn giả bị trễ. Bẫy: \"far more sign-ups\" là lý do đổi phòng workshop."},{"q":"Why does the speaker say, \"Room 2 only seats fifty\"?","o":["To complain about the venue","To suggest attendees arrive early","To explain why a session was relocated","To announce that a session is full"],"a":2,"ev":[4,5],"vi":"Workshop chuyển sang Grand Ballroom vì có quá nhiều người đăng ký mà \"Room 2 only seats fifty\" → giải thích lý do đổi phòng."},{"q":"What are listeners asked to do?","o":["Go to the terrace now","Refresh a mobile application","Register for another panel","Go to Room 2"],"a":1,"ev":[9],"vi":"\"The updated schedule is in the conference app, so please refresh it\" = làm mới ứng dụng. Bẫy: \"terrace\" là nơi ăn trưa lúc 12:30."}],"ts":[0.4,6.17,12.12,22.71,31.32,38.44,46.08,52.7,59.02,64.08,71.17]},{"id":"p4-27","part":4,"level":3,"topic":"Office","title":"Tips for remote meetings","title_vi":"Mẹo họp trực tuyến hiệu quả","speakers":{"A":"M-AU"},"lines":[["A","Welcome back to Work Smarter, the podcast for people who'd rather be doing their jobs than sitting in meetings. I'm Josh."],["A","Today's topic: running remote meetings that people actually want to attend."],["A","Tip number one: send the agenda at least twenty-four hours ahead."],["A","If people don't know why they're there, they won't come prepared."],["A","Tip two: keep it small. Research suggests decisions get harder once you go past about seven people."],["A","If someone only needs the outcome, send them the notes instead."],["A","Tip three: cameras. Now, I'm not going to tell you to force everyone to turn them on."],["A","But for discussions that need real decisions, do ask people to, because you'll pick up on reactions you'd otherwise miss."],["A","And tip four, my favourite: end five minutes early."],["A","Back-to-back calls are exhausting, and those five minutes give people a chance to grab a coffee or stretch."],["A","After the break, I'll be talking to Sarah Kim, a manager who cut her team's meeting time in half in just three months."],["A","Stick around."]],"questions":[{"q":"Who is the podcast most likely intended for?","o":["People looking for remote jobs","Workers frustrated by unproductive meetings","Managers hiring new staff","Researchers studying teamwork"],"a":1,"ev":[0],"vi":"\"the podcast for people who'd rather be doing their jobs than sitting in meetings\" → người đi làm chán họp (suy luận). Bẫy: \"remote\", \"Research\" có trong bài nhưng không phải đối tượng."},{"q":"According to the speaker, what should be done for people who only need the results?","o":["Invite them as observers","Ask them to keep cameras off","Send them the agenda a day early","Share a written summary with them"],"a":3,"ev":[5],"vi":"\"If someone only needs the outcome, send them the notes instead\" = gửi bản tóm tắt. Bẫy: gửi agenda trước 24 giờ áp dụng cho người dự họp."},{"q":"Why does the speaker say, \"I'm not going to tell you to force everyone to turn them on\"?","o":["To show he takes a flexible approach to cameras","To admit he dislikes video calls","To say cameras are against company policy","To suggest cameras cause technical problems"],"a":0,"ev":[6,7],"vi":"Anh không ép bật camera nhưng \"for discussions that need real decisions, do ask people to\" → quan điểm linh hoạt, tùy tình huống."},{"q":"What will listeners hear after the break?","o":["A fifth tip about meetings","Research on team size","A conversation with a manager","Advice on taking coffee breaks"],"a":2,"ev":[10],"vi":"\"After the break, I'll be talking to Sarah Kim, a manager\" = cuộc trò chuyện với một quản lý (paraphrase). Bẫy: chỉ có bốn mẹo; nghiên cứu và nghỉ uống cà phê đã nói rồi."}],"ts":[0.4,7.73,12.6,17.19,21.19,28.55,32.79,39.35,46.62,50.85,57.08,64.23]},{"id":"p4-28","part":4,"level":1,"topic":"Service","title":"Charger recall","title_vi":"Thu hồi bộ sạc lỗi","speakers":{"A":"F-US"},"lines":[["A","This is an important safety announcement from VoltEdge Electronics."],["A","We are recalling our PowerQuick sixty-five watt laptop charger, model number PQ-65."],["A","The recall covers chargers sold between March and August of this year."],["A","We have found that some of these chargers can overheat and, in rare cases, cause burns."],["A","So far, we have received eight reports of overheating, but no serious injuries."],["A","If you own one of these chargers, please stop using it immediately and unplug it."],["A","You can check your model number on the back of the charger."],["A","To get a free replacement, visit our website at voltedge dot com slash recall, or call our customer service line."],["A","You don't need a receipt."],["A","Replacement chargers will be shipped within ten business days."],["A","We are very sorry for the inconvenience, and we thank you for your understanding."]],"questions":[{"q":"What is the purpose of the announcement?","o":["To advertise a new laptop","To warn customers about a faulty product","To announce a price change","To explain a shipping delay"],"a":1,"ev":[0,1],"vi":"\"important safety announcement ... We are recalling our ... laptop charger\" → cảnh báo khách về sản phẩm lỗi và thu hồi."},{"q":"What is the problem with the product?","o":["It can get too hot","It charges slowly","It is too heavy","It has the wrong plug"],"a":0,"ev":[3],"vi":"\"some of these chargers can overheat\" = có thể quá nóng (paraphrase \"get too hot\")."},{"q":"What are customers who own the charger asked to do first?","o":["Return it to the store","Bring their receipt","Call the store manager","Stop using the charger"],"a":3,"ev":[5],"vi":"\"please stop using it immediately and unplug it\". Bẫy: \"You don't need a receipt\" – không cần hóa đơn."},{"q":"How soon will replacement chargers be sent?","o":["Within eight days","In August","Within ten business days","Within sixty-five days"],"a":2,"ev":[9],"vi":"\"Replacement chargers will be shipped within ten business days\". Bẫy số: 8 là số báo cáo, 65 là công suất (watt), August là thời gian bán."}],"ts":[0.4,5.12,12.43,17.55,23.98,30.18,35.76,39.67,47.77,50.25,54.8]},{"id":"p4-29","part":4,"level":2,"topic":"IT","title":"Project kickoff","title_vi":"Khởi động dự án","speakers":{"A":"M-GB"},"lines":[["A","Morning, everyone, and welcome to the kickoff for Project Atlas, our new customer self-service portal."],["A","I'm Oliver, and I'll be the project manager from start to finish."],["A","Let me quickly run through who's doing what."],["A","Hana is leading the front-end team, and Raj is in charge of the back-end and the APIs."],["A","Quality assurance will be handled by Duc's team in Hanoi, who'll start testing from the second sprint."],["A","As for milestones, we're aiming for a working prototype by the end of February, a beta release in May, and the full launch in July."],["A","That July date is fixed, because it's tied to the client's annual conference."],["A","In other words, there's no room for it to slip."],["A","Our first deadline is much closer, though."],["A","By next Friday, I need each lead to send me a rough estimate of the effort for their area."],["A","We'll use those numbers to finalise the plan at our review meeting the following Tuesday."],["A","Right, let's take ten minutes for questions."]],"questions":[{"q":"What is the purpose of the meeting?","o":["To review a beta release","To plan a client conference","To launch a new project","To hire new developers"],"a":2,"ev":[0],"vi":"\"welcome to the kickoff for Project Atlas\" → khởi động dự án mới. Bẫy: \"beta release\", \"client's annual conference\" chỉ là mốc/chi tiết."},{"q":"Who is responsible for testing?","o":["Hana's team","Duc's team","Raj's team","Oliver"],"a":1,"ev":[4],"vi":"\"Quality assurance will be handled by Duc's team in Hanoi\" (QA = kiểm thử). Hana phụ trách front-end, Raj back-end."},{"q":"Why can't the launch date change?","o":["Testing will start late","The budget is limited","The beta is planned for May","It is linked to a client event"],"a":3,"ev":[6],"vi":"\"That July date is fixed, because it's tied to the client's annual conference\" = gắn với sự kiện của khách hàng. Bẫy: May là mốc beta."},{"q":"What must team leads do by next Friday?","o":["Submit effort estimates","Finish a prototype","Attend a review meeting","Start testing"],"a":0,"ev":[9],"vi":"\"By next Friday, I need each lead to send me a rough estimate of the effort\". Bẫy: họp review là thứ Ba sau đó; prototype hạn cuối tháng Hai."}],"ts":[0.4,7.73,12.4,15.97,22.34,29.17,37.92,43.31,47.29,51.17,57.25,63.15]},{"id":"p4-30","part":4,"level":3,"topic":"Office","title":"Office relocation timeline","title_vi":"Lịch chuyển văn phòng","speakers":{"A":"F-AU"},"lines":[["A","Hi everyone, quick update on the office move, since I know a lot of you have been asking."],["A","As you know, we were originally planning to move into the new building on Parker Street on the first of June."],["A","Unfortunately, the fit-out has run about three weeks behind, mainly because of a delay with the network cabling."],["A","So the new move date is Monday the twenty-second of June."],["A","Here's how it'll work. On Thursday the eighteenth, the movers will collect everything except your laptops."],["A","That means Friday the nineteenth will be a work-from-home day for everyone."],["A","Please pack your desk into the labelled crates by five p.m. on Wednesday the seventeenth. Crates will be handed out next week."],["A","Personal items are your responsibility, so take anything valuable home."],["A","Now, the new office has fewer car spaces than we have now."],["A","So if you were thinking of driving in on the first day, you may want to reconsider."],["A","Parking passes will be allocated by the facilities team, and I'll share the details closer to the date."],["A","Thanks for your patience, everyone."]],"questions":[{"q":"What is the main purpose of the talk?","o":["To update staff on a postponed move","To announce a new network system","To introduce the facilities team","To explain a new parking fee"],"a":0,"ev":[0,3],"vi":"\"quick update on the office move\" và ngày chuyển bị lùi sang 22/6 → cập nhật về việc chuyển văn phòng bị hoãn. Bẫy: \"network cabling\" chỉ là nguyên nhân."},{"q":"What has caused the delay?","o":["A shortage of movers","Problems with parking","Late installation of cables","A change of building"],"a":2,"ev":[2],"vi":"\"mainly because of a delay with the network cabling\" = lắp đặt cáp mạng bị chậm (paraphrase). Bẫy: \"movers\", \"parking\" xuất hiện ở ý khác."},{"q":"By when must employees pack their desks?","o":["Monday the 22nd","Wednesday the 17th","Thursday the 18th","Friday the 19th"],"a":1,"ev":[6],"vi":"\"pack your desk ... by five p.m. on Wednesday the seventeenth\". Bẫy ngày: 18 là ngày chuyển đồ, 19 làm ở nhà, 22 là ngày chuyển chính thức."},{"q":"Why does the speaker say, \"you may want to reconsider\"?","o":["To ask staff to work from home on Monday","To warn that Parker Street will be closed","To announce a new parking fee","To suggest that parking may not be available"],"a":3,"ev":[8,9],"vi":"Ngay trước đó: \"the new office has fewer car spaces\" → ngụ ý có thể không có chỗ đỗ xe nếu lái xe đến. Bẫy: ngày làm ở nhà là thứ Sáu 19, không phải thứ Hai."}],"ts":[0.4,7.11,14.42,22.26,27.0,35.25,40.85,50.59,56.58,61.53,67.19,74.62]}];